            setTextColor(Color.parseColor("#EEEFF3"))
            setPadding(0, 0, 0, 8)
        }
        col.addView(sect)

        engBtn = bigBtn("Движок: …") {
            val p = prefs()
            val cur = p.getString("ocr_engine", "lens")
