    /** Инициализация выбранного движка в OCR-потоке (блокирующая, ~2-5 с в первый раз). */
    private fun setOverlayAlpha(alpha: Float) {
        ui.post {
            try {
                mainRoot?.alpha = alpha
                frameView?.alpha = alpha
            } catch (e: Exception) { }
        }
    }

    private fun captureRegion(): Bitmap? {
        val mp = projection ?: return null
        // VirtualDisplay с AUTO_MIRROR зеркалит ВЕСЬ экран и СЖИМАЕТ его под
        // размер выдачи: раньше экран целиком ужимался в размер рамки, текст
        // мельчал до неузнаваемости и детектор не находил строк («текст не
        // найден в рамке»). Поэтому захват всегда полноэкранный, а рамка
        // вырезается из полученного кадра — как это делает overlay-translator.
        val s = screenSize()
        val full = captureScreen(mp, s.x, s.y) ?: return null
        val r = regionRatio()
        val l = r.left.coerceIn(0, full.width - 1)
        val t = r.top.coerceIn(0, full.height - 1)
        val cw = (r.right - r.left).coerceIn(8, full.width - l)
        val ch = (r.bottom - r.top).coerceIn(8, full.height - t)
        return try {
            val cropped = Bitmap.createBitmap(full, l, t, cw, ch)
            cropped
        } finally {
            full.recycle()
        }
    }

    /** Полноэкранный кадр через MediaProjection (пиксель-в-пиксель). */
    private fun captureScreen(mp: MediaProjection, w: Int, h: Int): Bitmap? {
        val density = resources.displayMetrics.densityDpi
        var reader: ImageReader? = null
        var vd: VirtualDisplay? = null
        return try {
            setOverlayAlpha(0.0f)
            Thread.sleep(150)
            reader = ImageReader.newInstance(w, h, PixelFormat.RGBA_8888, 2)
            vd = mp.createVirtualDisplay(
                "ocr-scan", w, h, density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                reader.surface, null, null
            )
            Thread.sleep(480)
            val img = reader.acquireLatestImage()
            if (img == null) return null
            val plane = img.planes[0]
            val buf = plane.buffer
            val pixelStride = plane.pixelStride
            val rowStride = plane.rowStride
            val rowPadding = rowStride - pixelStride * w
            val raw = Bitmap.createBitmap(w + rowPadding / pixelStride, h, Bitmap.Config.ARGB_8888)
            buf.rewind()
            raw.copyPixelsFromBuffer(buf)
            img.close()
            val exact = Bitmap.createBitmap(raw, 0, 0, w, h)
            raw.recycle()
            exact
        } catch (e: Exception) {
            null
        } finally {
            try { vd?.release() } catch (e: Exception) { }
            try { reader?.close() } catch (e: Exception) { }
            setOverlayAlpha(1f)
        }
    }

    private fun ocrScan(onText: (String) -> Unit) {
        ocrHandler.post {
            var text = ""
            try {
                val bmp = captureRegion()
                if (bmp != null) {
                    val keyHint = engineKeyHint()
                    if (keyHint != null) {
                        ui.post {
                            preview = "⚠ " + engineTitle() + ": " + keyHint
                            previewText?.text = preview
                        }
                    } else {
                        text = try {
                            when (engineId()) {
                                "zen" -> zenOcr.recognizeText(bmp)
                                "googleai" -> googleOcr.recognizeText(bmp)
                                "openrouter" -> orOcr.recognizeText(bmp)
                                else -> glensOcr.recognizeText(bmp)
                            }
                        } catch (e: Exception) {
                            android.util.Log.w("OcrNet", engineId() + ": " + e.message)
                            ""
                        }
                    }
                    try { bmp.recycle() } catch (e: Exception) { }
                }
            } catch (e: Exception) { }
            var out = text.replace("\\s+".toRegex(), " ").trim()
            // Режим «Перевод»: латиница → русский (Zen/Google Translate/MyMemory — онлайн).
            if (out.isNotBlank() && prefs.getBoolean("translate", false) && !ScriptDetect.isMostlyCyrillic(out)) {
                try {
                    val tr = translator.translate(out, EnginePrefs.TR_AUTO, EnginePrefs.MODE_ONLINE)
                    if (!tr.isNullOrBlank() && tr != out) out = tr
                } catch (e: Exception) {
                    android.util.Log.d("OcrTr", "translate: " + e.message)
                }
            }
            ui.post { onText(out) }
        }
    }

