package app.yomikaioverlay.ot

import android.content.Context
import org.json.JSONObject

/**
 * Bundled EN→RU dictionary (from the desktop ScreenOCR_TTS corpus) used for
 * fully-offline per-word translation. Loaded from assets lazily; the file is
 * a flat JSON map of lowercase English word → UPPERCASE Russian sense.
 */
class LocalDictionary(private val ctx: Context) {

    @Volatile
    private var words: Map<String, String>? = null

    private fun load(): Map<String, String> {
        words?.let { return it }
        val loaded = runCatching {
            val raw = ctx.assets.open("dict/en_ru.json").bufferedReader()
                .use { it.readText() }
            val obj = JSONObject(raw)
            val keys = obj.keys()
            val map = HashMap<String, String>((obj.length().toDouble() / 0.75f).toInt())
            while (keys.hasNext()) {
                val k = keys.next()
                map[k] = obj.getString(k)
            }
            map
        }.getOrNull() ?: emptyMap()
        words = loaded
        return loaded
    }

    /**
     * Looks up a single token. Returns null when the dictionary was not loaded
     * or the token is not present. Matching is case- and punctuation-insensitive.
     */
    fun lookup(raw: String): String? {
        val token = raw.trim().trim('«', '»', '"', '\'', ',', '.', '!', '?', ':', ';', '(', ')', '-', '—')
        if (token.isEmpty()) return null
        val key = token.lowercase()
        val hit = load()[key] ?: return null
        return hit
    }

    /**
     * Translates a whole fragment token-by-token, keeping unknown words and any
     * non-letter spans intact. Unknown or Cyrillic words are passed through.
     */
    fun translateFragment(text: String): String {
        if (!isUsable()) return text
        val found = StringBuilder(text.length)
        val token = StringBuilder()
        var tokenChanged = false
        fun flush() {
            if (token.isNotEmpty()) {
                val t = token.toString()
                val tr = if (tokenChanged) null else lookup(t) ?: t
                found.append(tr)
                token.setLength(0)
                tokenChanged = false
            }
        }
        for (ch in text) {
            if (ch.isLetter()) {
                token.append(ch)
            } else {
                flush()
                found.append(ch)
            }
        }
        flush()
        return found.toString()
    }

    private fun isUsable(): Boolean {
        return load().isNotEmpty()
    }
}

package app.yomikaioverlay

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.graphics.Path
import android.view.accessibility.AccessibilityEvent

/**
 * Служба спецвозможностей для автопрокрутки страниц во время авточтения.
 * Делает свайп вверх внутри OCR-рамки (как палец по экрану).
 *
 * ВАЖНО: на Android 13+ для приложений, установленных APK-файлом, система
 * может блокировать включение («Доступ к настройкам ограничен»). Снятие
 * блокировки: Настройки → Приложения → Yomikai Оверлей → меню ⋮ →
 * «Разрешить ограниченные настройки», затем включить службу снова.
 */
class ScrollAccessibilityService : AccessibilityService() {

    companion object {
        @Volatile
        var instance: ScrollAccessibilityService? = null
            private set
    }

    override fun onServiceConnected() {
        instance = this
    }

    override fun onUnbind(intent: android.content.Intent?): Boolean {
        instance = null
        return super.onUnbind(intent)
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {}

    override fun onInterrupt() {}

    /** Свайп «листание вперёд» внутри области [left,top,right,bottom] (пиксели экрана). */
    fun swipeForward(left: Int, top: Int, right: Int, bottom: Int): Boolean {
        val cx = clamp((left + right) / 2, 1, widthGuess() - 1).toFloat()
        val h = (bottom - top).coerceAtLeast(120)
        val yFrom = (top + h * 0.80f).toInt()
        val yTo = (top + h * 0.38f).toInt()
        return swipe(cx, yFrom.toFloat(), cx, yTo.toFloat())
    }

    private fun swipe(x1: Float, y1: Float, x2: Float, y2: Float): Boolean {
        return try {
            val path = Path().apply {
                moveTo(x1, y1)
                lineTo(x2, y2)
            }
            val gesture = GestureDescription.Builder()
                .addStroke(GestureDescription.StrokeDescription(path, 0L, 380L))
                .build()
            dispatchGesture(gesture, null, null)
        } catch (e: Exception) {
            false
        }
    }

    private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

    private fun widthGuess(): Int = resources.displayMetrics.widthPixels.coerceAtLeast(1)
}

package app.yomikaioverlay

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.media.projection.MediaProjectionManager
import android.os.Bundle
import android.widget.Toast

/**
 * Прозрачная activity, которая добывает разрешение на захват экрана
 * (MediaProjection consent). Система строго требует: диалог может вызвать
 * только activity, поэтому сервис передаёт запрос через неё.
 */
class CaptureConsentActivity : Activity() {

    companion object {
        private const val REQ_CAPTURE = 42

        fun request(context: Context, next: String) {
            val i = Intent(context, CaptureConsentActivity::class.java)
            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_NO_HISTORY)
            i.putExtra("next", next)
            context.startActivity(i)
        }
    }

    private var asked = false

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        ask()
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        setIntent(intent)
        ask()
    }

    private fun ask() {
        if (asked) return
        asked = true
        try {
            val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE) as MediaProjectionManager
            @Suppress("DEPRECATION")
            startActivityForResult(mpm.createScreenCaptureIntent(), REQ_CAPTURE)
        } catch (e: Exception) {
            Toast.makeText(this, "Захват экрана не поддержан: ${e.message}", Toast.LENGTH_LONG).show()
            finish()
        }
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == REQ_CAPTURE) {
            if (resultCode == RESULT_OK && data != null) {
                val next = intent.getStringExtra("next") ?: "scan"
                OverlayService.startForegroundService(this) // поднять сервис, если ещё не
                val s = Intent(this, OverlayService::class.java)
                s.action = OverlayService.ACTION_PROJECTION
                s.putExtra("resultCode", resultCode)
                s.putExtra("data", data)
                s.putExtra("next", next)
                startService(s)
            } else {
                Toast.makeText(this, "Захват экрана отклонён", Toast.LENGTH_SHORT).show()
            }
        }
        finish()
    }
}

