        if (amp >= 0 && part.indexOf(';', amp) < 0 && part.length > amp + 1) {
            part = part.substring(0, amp)
        }
        if (part.isNotEmpty()) chunks += part.trim()
        rest.delete(0, part.length.coerceAtLeast(1))
    }
    return chunks.filter(String::isNotBlank)
}

