    fun readString(): String = readBytes().toString(Charsets.UTF_8)

    fun skipField(wireType: Int) {
        when (wireType) {
            0 -> readVarint32()
            1 -> { pos += 8; if (pos > bytes.size) pos = bytes.size }
            2 -> { val len = readVarint32() ?: 0; pos += len.coerceAtMost(bytes.size - pos); if (pos > bytes.size) pos = bytes.size }
            5 -> { pos += 4; if (pos > bytes.size) pos = bytes.size }
        }
    }

    internal fun readVarint32(): Int? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result.toInt()
            shift += 7
        }
        return result.toInt()
    }

    /** Полный 64-битный varint: длинные значения (uint64) больше не рвут поток. */
    internal fun readVarint64(): Long? {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) return null
            val b = bytes[pos++].toLong() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80L) == 0L) return result
            shift += 7
        }
        return result
    }
}

