/**
 * Разбивает текст на куски ≤ [SSML_BYTE_LIMIT] байт UTF-8, не режа символы:
 * большой текст уходит несколькими SSML-запросами. Лимит — в БАЙТАХ:
 * кириллица занимает 2 байта на символ, поэтому считать символы нельзя.
 */
internal fun chunkForSsml(text: String, limit: Int = SSML_BYTE_LIMIT): List<String> {
    if (text.isBlank()) return emptyList()
    if (text.toByteArray(Charsets.UTF_8).size <= limit) return listOf(text)
    val chunks = mutableListOf<String>()
    val rest = StringBuilder(text)
    while (rest.isNotEmpty()) {
        // набираем подстроку, пока её UTF-8 размер не упрётся в лимит
        var take = 0
        var size = 0
        while (take < rest.length) {
            val chSize = utf8Size(rest[take])
            if (size + chSize > limit && take > 0) break
            size += chSize
            take++
        }
        if (take <= 0) take = 1
        var part = rest.substring(0, take)
        val amp = part.lastIndexOf('&')
        if (amp >= 0 && part.indexOf(';', amp) < 0 && part.length > amp) {
            // не оставляем хвост с «висячим» & (резал бы XML-сущность)
            part = part.substring(0, amp)
        }
        if (part.isNotEmpty()) chunks += part.trim()
        rest.delete(0, part.length.coerceAtLeast(1))
    }
    return chunks.filter(String::isNotBlank)
}

/** Размер символа в UTF-8 (суррогатная пара = 2+2 байта). */
private fun utf8Size(ch: Char): Int = when (ch.code) {
    in 0 until 0x80 -> 1
    in 0x80 until 0x800 -> 2
    in 0xD800..0xDFFF -> 2
    else -> 3
}

