object ScriptDetect {
    fun isMostlyCyrillic(text: String): Boolean {
        var cyr = 0
        var lat = 0
        for (ch in text) {
            when (ch) {
                in 'А'..'я', 'Ё', 'ё' -> cyr++
                // только буквы: диапазон 'A'..'z' затянул бы [ \ ] ^ _ `
                in 'A'..'Z', in 'a'..'z' -> lat++
            }
        }
        return cyr > 0 && cyr >= lat
    }

    fun preferRu(text: String): Boolean = isMostlyCyrillic(text)
}

