     private fun grantProjection(resultCode: Int, data: Intent) {
         try {
             val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE) as MediaProjectionManager
             val mp = mpm.getMediaProjection(resultCode, data)
             if (Build.VERSION.SDK_INT >= 29) {
                 // Callback во всех версиях, где он есть: если пользователь или
                 // система остановили захват, сервис должен узнать об этом
                 // сразу, а не продолжать показывать «работает».
                 mp.registerCallback(object : MediaProjection.Callback() {
                     override fun onStop() {
                         projection = null
                         projectionGranted = false
                         autoReading = false
                         speakGen++
+                        releaseDisplay()
                         preview = "⚠ Захват экрана остановлен — повторите скан"
                         ui.post {
                             previewText?.text = preview
                             rebuildPanel()
                             refreshFrame()
                             notifyStatus(preview)
                         }
                     }
                 }, ui)
             }
             projection = mp
             projectionGranted = true
+            bindProjection(mp)
             ensureForeground(true)
         } catch (e: Exception) {
             Toast.makeText(this, "Захват экрана не запустился: ${e.message}", Toast.LENGTH_LONG).show()
         }
     }

     private fun scanOnceOrAsk() {
         if (!projectionGranted) CaptureConsentActivity.request(this, "scan") else scanOnce()
     }

     private fun startAutoReadOrAsk() {
         if (!projectionGranted) CaptureConsentActivity.request(this, "read") else startAutoRead()
     }

