display.text:
/**
 * Прячет все окна оверлея на время захвата экрана. Раньше скрывались
 * только пузырь и рамка — окно выбора голоса/рамки с затемнением
 * попадало в скриншот и ломало OCR.
 */
private fun setOverlayAlpha(alpha: Float) {
    ui.post {
        try {
            mainRoot?.alpha = alpha
            frameView?.alpha = alpha
            voiceWin?.alpha = alpha
            selectRoot?.alpha = alpha
        } catch (e: Exception) { }
    }
}

private fun captureRegion(): Bitmap? {
    val mp = projection ?: return null
    // VirtualDisplay с AUTO_MIRROR зеркалит ВЕСЬ экран и СЖИМАЕТ его под
    // размер выдачи: раньше экран целиком ужимался в размер рамки, текст
    // мельчал до неузнаваемости и детектор не находил строк («текст не
    // найден в рамке»). Поэтому захват всегда полноэкранный, а рамка
    // вырезается из полученного кадра — как это делает overlay-translator.
    val s = screenSize()
    val full = captureScreen(mp, s.x, s.y) ?: return null
    val r = regionRatio()
    val l = r.left.coerceIn(0, full.width - 1)
    val t = r.top.coerceIn(0, full.height - 1)
    val cw = (r.right - r.left).coerceIn(8, full.width - l)
    val ch = (r.bottom - r.top).coerceIn(8, full.height - t)
    return try {
        val cropped = Bitmap.createBitmap(full, l, t, cw, ch)
        cropped
    } finally {
        full.recycle()
    }
}

/** Полноэкранный кадр через MediaProjection (пиксель-в-пиксель). */
private fun captureScreen(mp: MediaProjection, w: Int, h: Int): Bitmap? {
    val density = resources.displayMetrics.densityDpi
    var reader: ImageReader? = null
    var vd: VirtualDisplay? = null
    return try {
        setOverlayAlpha(0.0f)
        Thread.sleep(150)
        reader = ImageReader.newInstance(w, h, PixelFormat.RGBA_8888, 2)
        vd = mp.createVirtualDisplay(
            "ocr-scan", w, h, density,
            DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
            reader.surface, null, null
        )
        Thread.sleep(480)
        val img = reader.acquireLatestImage()
        if (img == null) return null
        val plane = img.planes[0]
        val buf = plane.buffer
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        // На части устройств rowStride < pixelStride*w (не должно, но бывает):
        // страховка от createBitmap с отрицательной шириной.
        val rowPadding = (rowStride - pixelStride * w).coerceAtLeast(0)
        val rawWidth = (w + rowPadding / pixelStride).coerceAtLeast(w)
        val raw = Bitmap.createBitmap(rawWidth, h, Bitmap.Config.ARGB_8888)
        buf.rewind()
        raw.copyPixelsFromBuffer(buf)
        img.close()
        val exact = Bitmap.createBitmap(raw, 0, 0, w, h)
        raw.recycle()
        exact
    } catch (e: Exception) {
        null
    } finally {
        try { vd?.release() } catch (e: Exception) { }
        try { reader?.close() } catch (e: Exception) { }
        setOverlayAlpha(1f)
    }
}

private fun ocrScan(onText: (String) -> Unit) {
    ocrHandler.post {
        var text = ""
        var hint: String? = null
        try {
            val bmp = captureRegion()
            if (bmp != null) {
                val keyHint = engineKeyHint()
                if (keyHint != null) {
                    hint = "⚠ " + engineTitle() + ": " + keyHint
                } else {
                    text = try {
                        when (engineId()) {
                            Engines.ZEN -> zenOcr.recognizeText(bmp)
                            Engines.GOOGLE_AI -> googleOcr.recognizeText(bmp)
                            Engines.OPENROUTER -> orOcr.recognizeText(bmp)
                            else -> glensOcr.recognizeText(bmp)
                        }
                    } catch (e: Exception) {
                        android.util.Log.w("OcrNet", engineId() + ": " + e.message)
                        ""
                    }
                }
                try { bmp.recycle() } catch (e: Exception) { }
            }
        } catch (e: Exception) { }
        var out = text.replace("\\s+".toRegex(), " ").trim()
        // Режим «Перевод»: латиница → русский (Zen/Google Translate/MyMemory — онлайн).
        if (out.isNotBlank() && prefs.getBoolean("translate", false) && !ScriptDetect.isMostlyCyrillic(out)) {
            try {
                val tr = translator.translate(out, EnginePrefs.TR_AUTO, EnginePrefs.MODE_ONLINE)
                if (!tr.isNullOrBlank() && tr != out) out = tr
            } catch (e: Exception) {
                android.util.Log.d("OcrTr", "translate: " + e.message)
            }
        }
        ui.post {
            if (hint != null && out.isBlank()) {
                preview = hint
                previewText?.text = preview
            }
            onText(out)
        }
    }
}

// ------------------------------------------------------------------
// TTS
// ------------------------------------------------------------------

private fun ensureTts() {
    if (tts != null) return
    try {
        tts = TextToSpeech(applicationContext) { status ->
            ttsReady = (status == TextToSpeech.SUCCESS)
            val t = tts ?: return@TextToSpeech
            try { t.setSpeechRate(prefs.getFloat("rate", 1.0f)) } catch (e: Exception) { }
            t.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                override fun onStart(utteranceId: String?) {
                    speaking = true
                }
                @Deprecated("dep")
                override fun onError(utteranceId: String?) { onDone(utteranceId) }
                override fun onError(utteranceId: String?, errorCode: Int) {
                    onDone(utteranceId)
                }
                override fun onStop(utteranceId: String?, interrupted: Boolean) {
                    onDone(utteranceId)
                }
                override fun onDone(utteranceId: String?) {
                    ui.post {
                        speaking = false
                        if (autoReading) {
                            ui.postDelayed({ if (autoReading) scrollAndContinue() }, 350)
                        }
                    }
                }
            })
        }
    } catch (e: Exception) {
        tts = null
        ttsReady = false
    }
}

/** Применяет сохранённый голос (по имени из выбора), если задан. */
private fun applyVoicePref(t: TextToSpeech) {
    val name = prefs.getString("voice_name", "") ?: ""
    if (name.isBlank()) return
    try {
        val v = t.voices?.firstOrNull { it.name == name } ?: return
        t.voice = v
    } catch (e: Exception) { }
}

private fun currentVoiceLabel(): String {
    val name = prefs.getString("voice_name", "") ?: ""
    if (name.startsWith("edge:")) return name.removePrefix("edge:").take(26) + " · Edge"
    if (name.isBlank()) return (if (ttsBackend() == "edge") edgeVoiceName().take(22) + " · Edge" else "голос системы")
    return name.replace("language", "").trim('-', ' ').take(26)
}

package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.util.Log
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import kotlin.random.Random

/**
 * Google Lens OCR via protobuf endpoint.
 * Ported from Yomihon's GlensOcrEngine.
 *
 * Falls back gracefully: returns empty string on any error so that
 * [OcrRouter] can try the next engine.
 */
class GlensOcrEngine : OcrEngine {

    override fun recognizeText(image: Bitmap): String {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val maxDim = maxOf(image.width, image.height)
        val resized = if (maxDim > MAX_IMAGE_DIMENSION) {
            val s = MAX_IMAGE_DIMENSION.toFloat() / maxDim.toFloat()
            Bitmap.createScaledBitmap(image, 
                (image.width * s).toInt().coerceAtLeast(1),
                (image.height * s).toInt().coerceAtLeast(1),
                true,
            )
        } else null
        val working = resized ?: image
        return try {
            val encoded = ByteArrayOutputStream()
            if (!working.compress(Bitmap.CompressFormat.PNG, 100, encoded))
                throw IOException("PNG encode failed")
            val payload = buildRequestPayload(encoded.toByteArray(), working.width, working.height)
            val resp = executeRequest(payload)
            extractText(resp)
        } catch (e: Exception) {
            Log.w(TAG, "Glens failed, returning empty", e)
            ""
        } finally {
            resized?.recycle()
        }
    }

    /* ─────────── Request ─────────── */

    internal fun buildRequestPayload(pngBytes: ByteArray, w: Int, h: Int): ByteArray {
        // Must be non-negative for uint64 varint encoding
        val requestId = Random.nextLong().toLong() and Long.MAX_VALUE
        return ProtoWriter().apply {
            writeMessage(1) { objReq ->
                // objects_request_context
                objReq.writeMessage(1) { ctx ->
                    // request_id
                    ctx.writeMessage(3) { rid ->
                        rid.writeUInt64(1, requestId)
                        rid.writeInt32(2, 0)
                        rid.writeInt32(3, 0)
                        rid.writeBytes(4, Random.nextBytes(16))
                    }
                    // client_context
                    ctx.writeMessage(4) { cc ->
                        cc.writeInt32(1, PLATFORM_WEB)
                        cc.writeInt32(2, SURFACE_CHROMIUM)
                        cc.writeMessage(4) { lc ->
                            lc.writeString(1, DEFAULT_CLIENT_LANGUAGE)
                            lc.writeString(2, DEFAULT_CLIENT_REGION)
                        }
                        cc.writeMessage(7) { filters ->
                            filters.writeMessage(1) { fl ->
                                fl.writeInt32(1, AUTO_FILTER)
                            }
                        }
                    }
                }
                // image_data
                objReq.writeMessage(3) { img ->
                    img.writeMessage(1) { p ->
                        p.writeBytes(1, pngBytes)
                    }
                    img.writeMessage(3) { m ->
                        m.writeInt32(1, w)
                        m.writeInt32(2, h)
                    }
                }
            }
        }.toByteArray()
    }

    /* ─────────── HTTP ─────────── */

    private fun executeRequest(payload: ByteArray): ByteArray {
        val conn = (URL(LENS_ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 10_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/x-protobuf")
            setRequestProperty("User-Agent", DEFAULT_USER_AGENT)
            setRequestProperty("X-Goog-Api-Key", API_KEY)
        }
        return try {
            conn.outputStream.use { it.write(payload) }
            val status = conn.responseCode
            val bytes = (if (status in 200..299) conn.inputStream else conn.errorStream)
                ?.use { it.readBytes() } ?: ByteArray(0)
            if (status !in 200..299)
                throw IOException("HTTP $status: ${bytes.toString(Charsets.UTF_8).take(200)}")
            bytes
        } finally {
            conn.disconnect()
        }
    }

    /* ─────────── Response parser ─────────── */

    private fun extractText(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val allLines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                allLines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return allLines.joinToString("\n").trim()
    }

    private fun parseObjectsResponse(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 3 && wire == 2) lines += parseText(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseText(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val result = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) result += parseTextLayout(reader.readBytes())
            else reader.skipField(wire)
        }
        return result
    }

    private fun parseTextLayout(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) lines += parseParagraph(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    private fun parseParagraph(bytes: ByteArray): List<String> {
        val reader = ProtoReader(bytes)
        val lines = mutableListOf<String>()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 2 && wire == 2) lines += parseLine(reader.readBytes())
            else reader.skipField(wire)
        }
        return lines
    }

    /** A "line" is a sequence of words; each word carries its own trailing separator. */
    private fun parseLine(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        val sb = StringBuilder()
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                sb.append(parseWord(reader.readBytes()))
            } else {
                reader.skipField(wire)
            }
        }
        return sb.toString()
    }

    /** Returns text + separator (e.g. "Hello" + " "). */
    private fun parseWord(bytes: ByteArray): String {
        val reader = ProtoReader(bytes)
        var text = ""
        var separator = ""
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag ushr 3; val wire = tag and 0x7
            when {
                field == 2 && wire == 2 -> text = reader.readString()
                field == 3 && wire == 2 -> separator = reader.readString()
                else -> reader.skipField(wire)
            }
