import struct, random, os, urllib.request, sys

def vu(n):
    out=bytearray()
    while True:
        b=n&0x7f; n>>=7
        if n: out.append(b|0x80)
        else: out.append(b); break
    return bytes(out)
def tag(f,w): return vu((f<<3)|w)
def ms(f,p): return tag(f,2)+vu(len(p))+p
def st(f,s): return ms(f, s.encode())
def i32(f,v): return tag(f,0)+vu(v)

def build(png,w,h,lang,region):
    rid = random.getrandbits(63)
    ridmsg = i32(1,rid)+i32(2,0)+i32(3,0)+ms(4, os.urandom(16))
    lc = st(1,lang)+st(2,region)
    cc = i32(1,3)+i32(2,4)+ms(4,lc)+ms(7,ms(1,i32(1,1)))
    ctx = ms(3,ridmsg)+ms(4,cc)
    img = ms(1, ms(1,png)) + ms(3, i32(1,w)+i32(2,h))
    return ms(1, ms(1,ctx)+ms(3,img))

# ---- exact port of Kotlin ProtoReader/extract ----
class R:
    def __init__(s,b): s.b=b; s.p=0
    def rem(s): return s.p<len(s.b)
    def v32(s):
        res=0; sh=0
        while sh<64:
            if not s.rem(): return None
            x=s.b[s.p]; s.p+=1
            res |= (x&0x7f)<<sh
            if not (x&0x80): return res
            sh+=7
        return res
    def rbytes(s):
        ln=s.v32()
        if ln is None: return b""
        ln=min(ln, len(s.b)-s.p)
        r=s.b[s.p:s.p+ln]; s.p+=ln; return r
    def rstr(s): return s.rbytes().decode('utf-8','replace')
    def skip(s,w):
        if w==0: s.v32()
        elif w==1: s.p=min(s.p+8,len(s.b))
        elif w==2:
            ln=s.v32() or 0; s.p=min(s.p+ln,len(s.b))
        elif w==5: s.p=min(s.p+4,len(s.b))

def extract(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==2 and w==2: lines += objects(r.rbytes())
        else: r.skip(w)
    return "\n".join(lines).strip()

def objects(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==3 and w==2: lines += ptext(r.rbytes())
        else: r.skip(w)
    return lines
def ptext(b):
    r=R(b); res=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: res += playout(r.rbytes())
        else: r.skip(w)
    return res
def playout(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: lines += ppara(r.rbytes())
        else: r.skip(w)
    return lines
def ppara(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==2 and w==2: lines.append(pline(r.rbytes()))
        else: r.skip(w)
    return lines
def pline(b):
    r=R(b); sb=""
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: sb+=pword(r.rbytes())
        else: r.skip(w)
    return sb
def pword(b):
    r=R(b); text=""; sep=""
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==2 and w==2: text=r.rstr()
        elif f==3 and w==2: sep=r.rstr()
        else: r.skip(w)
    return text+sep

def run(pngpath, w,h, lang, region):
    png=open(pngpath,'rb').read()
    payload=build(png,w,h,lang,region)
    req=urllib.request.Request("https://lensfrontend-pa.googleapis.com/v1/crupload", data=payload,
        headers={"Content-Type":"application/x-protobuf",
                 "X-Goog-Api-Key":"AIzaSyDr2UxVnv_U85AbhhY8XSHSIavUW0DC-sY",
                 "User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36"})
    data=urllib.request.urlopen(req, timeout=30).read()
    txt=extract(data)
    print(f"{pngpath} lang={lang:3} -> {txt!r}")

for p in sys.argv[1:] or ["text_test.png"]:
    for lang,region in [("ja","Asia/Tokyo"),("ru","Europe/Moscow"),("en","US")]:
        try: run(p,700,200,lang,region)
        except Exception as e: print(p,lang,"ERR",type(e).__name__,e)
