def objects(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==3 and w==2: lines += ptext(r.rbytes())
        else: r.skip(w)
    return lines
def ptext(b):
    r=R(b); res=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: res += playout(r.rbytes())
        else: r.skip(w)
    return res
def playout(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: lines += ppara(r.rbytes())
        else: r.skip(w)
    return lines
def ppara(b):
    r=R(b); lines=[]
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==2 and w==2: lines.append(pline(r.rbytes()))
        else: r.skip(w)
    return lines
def pline(b):
    r=R(b); sb=""
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==1 and w==2: sb+=pword(r.rbytes())
        else: r.skip(w)
    return sb
def pword(b):
    r=R(b); text=""; sep=""
    while r.rem():
        t=r.v32()
        if t is None: break
        f=t>>3; w=t&7
        if f==2 and w==2: text=r.rstr()
        elif f==3 and w==2: sep=r.rstr()
        else: r.skip(w)
