     override fun onCreate() {
         super.onCreate()
         running = true
         wm = getSystemService(Context.WINDOW_SERVICE) as WindowManager
         prefs = getSharedPreferences("ovr", MODE_PRIVATE)
         ui = Handler(mainLooper)
         val th = HandlerThread("overlay-ocr")
         th.start()
         ocrThread = th
         ocrHandler = Handler(th.looper)
         ensureForeground(false)
         buildWindows()
     }

     override fun onBind(intent: Intent?): IBinder? = null

     override fun onDestroy() {
         running = false
         autoReading = false
         speakGen++ // всё, что синтезируется в фоне, уже не проигрываем
         ui.removeCallbacksAndMessages(null)
         try { tts?.stop(); tts?.shutdown() } catch (e: Exception) { }
         tts = null
         ttsReady = false
         releaseDisplay()
         try { projection?.stop() } catch (e: Exception) { }
         projection = null
         projectionGranted = false
         removeAllWindows()
         try { ocrThread?.quitSafely() } catch (e: Exception) { }
         try { wakeLock?.let { if (it.isHeld) it.release() } } catch (e: Exception) { }
         super.onDestroy()
     }

     override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
         when (intent?.action) {
             ACTION_START -> {
                 ensureForeground(projectionGranted)
                 showMain(true)
             }
             ACTION_SCAN_ONCE -> {
                 ensureForeground(projectionGranted)
                 if (!projectionGranted) {
                     CaptureConsentActivity.request(this, "scan")
                 } else {
                     scanOnce()
                 }
             }
             ACTION_AUTO_READ -> {
                 ensureForeground(projectionGranted)
                 if (!projectionGranted) {
                     CaptureConsentActivity.request(this, "read")
                 } else {
                     startAutoRead()
                 }
             }
             ACTION_READ_TOGGLE -> {
                 if (autoReading) stopAutoRead() else startAutoReadOrAsk()
             }
             ACTION_PROJECTION -> {
                 val rc = intent.getIntExtra("resultCode", 0)
                 @Suppress("DEPRECATION")
                 val data = if (Build.VERSION.SDK_INT >= 33) {
                     intent.getParcelableExtra("data", Intent::class.java)
                 } else {
                     intent.getParcelableExtra("data")
                 }
                 if (rc != 0 && data != null) {
                     grantProjection(rc, data)
                     when (intent.getStringExtra("next")) {
                         "read" -> startAutoRead()
                         else -> scanOnce()
                     }
                 }
             }
             else -> {
                 // START_STICKY-перезапуск приходит с null-intent: без повторного
                 // startForeground система убивает сервис по таймауту.
                 ensureForeground(projectionGranted)
                 showMain(true)
             }
         }
         return START_STICKY
     }

     // ------------------------------------------------------------------
     // Foreground: двухфазно (mediaPlayback → +mediaProjection после consent),
     // иначе Android 14+ роняет сервис SecurityException'ом («в других местах»).
     // ------------------------------------------------------------------

     /** Обновляет уведомление сервиса: распознанный текст виден прямо в шторке,
      * плюс кнопки-экшены «OCR скан» и «Авточтение/Стоп». */
     private fun notifyStatus(text: String?) {
         try {
             val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
             val content = if (text.isNullOrBlank()) getString(R.string.notif_text) else text
             val scanPi = PendingIntent.getService(
                 this, 1,
                 Intent(this, OverlayService::class.java).apply { action = ACTION_SCAN_ONCE },
                 PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
             )
             val readPi = PendingIntent.getService(
                 this, 2,
                 Intent(this, OverlayService::class.java).apply { action = ACTION_READ_TOGGLE },
                 PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
             )
             val b: Notification.Builder = if (Build.VERSION.SDK_INT >= 26) {
                 Notification.Builder(this, CH_ID)
             } else {
                 @Suppress("DEPRECATION")
                 Notification.Builder(this)
             }
             b.setSmallIcon(R.drawable.ic_scan)
                 .setContentTitle(getString(R.string.app_name))
                 .setContentText(if (content.length > 160) content.take(160) + "…" else content)
                 .setContentIntent(
                     PendingIntent.getActivity(
                         this, 0, Intent(this, MainActivity::class.java),
                         PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                     )
                 )
                 .setOngoing(true)
             if (content.isNotBlank() && content != getString(R.string.notif_text)) {
                 b.setStyle(Notification.BigTextStyle().bigText(content))
             }
             b.addAction(Notification.Action.Builder(null, "OCR скан", scanPi).build())
             b.addAction(
                 Notification.Action.Builder(
                     null, if (autoReading) "Стоп чтения" else "Авточтение", readPi
                 ).build()
             )
             nm.notify(NOTIF_ID, b.build())
         } catch (e: Exception) {
             android.util.Log.w("OverlayService", "notifyStatus: ${e.message}")
         }
     }

     private fun ensureForeground(withProjection: Boolean) {
         val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
         if (Build.VERSION.SDK_INT >= 26) {
             if (nm.getNotificationChannel(CH_ID) == null) {
                 val ch = NotificationChannel(CH_ID, getString(R.string.notif_channel), NotificationManager.IMPORTANCE_MIN)
                 nm.createNotificationChannel(ch)
             }
         }
         val pi = PendingIntent.getActivity(
             this, 0, Intent(this, MainActivity::class.java),
             PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
         )
         val n: Notification = if (Build.VERSION.SDK_INT >= 26) {
             Notification.Builder(this, CH_ID)
                 .setSmallIcon(R.drawable.ic_scan)
                 .setContentTitle(getString(R.string.app_name))
                 .setContentText(getString(R.string.notif_text))
                 .setContentIntent(pi)
                 .setOngoing(true)
                 .build()
         } else {
             @Suppress("DEPRECATION")
             Notification.Builder(this)
                 .setSmallIcon(R.drawable.ic_scan)
                 .setContentTitle(getString(R.string.app_name))
                 .setContentText(getString(R.string.notif_text))
                 .setContentIntent(pi)
                 .setOngoing(true)
                 .build()
         }
         try {
             if (Build.VERSION.SDK_INT >= 29) {
                 var type = ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK
                 if (withProjection) {
                     type = type or ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION
                 }
                 startForeground(NOTIF_ID, n, type)
             } else {
                 startForeground(NOTIF_ID, n)
             }
         } catch (se: SecurityException) {
             // Крайняя страховка: подняться без типа, но сервис должен жить.
             runCatching { startForeground(NOTIF_ID, n) }
         }
     }

