         TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics
     ).toInt()

     private fun screenSize(): Point {
         return try {
             if (Build.VERSION.SDK_INT >= 30) {
                 val b = wm.currentWindowMetrics.bounds
                 if (b.width() > 0 && b.height() > 0) return Point(b.width(), b.height())
             }
             val p = Point()
             @Suppress("DEPRECATION")
             wm.defaultDisplay.getRealSize(p)
             if (p.x <= 0 || p.y <= 0) {
                 val dm = resources.displayMetrics
                 p.set(dm.widthPixels, dm.heightPixels)
             }
             p
         } catch (e: Exception) {
             val dm = resources.displayMetrics
             Point(dm.widthPixels, dm.heightPixels)
         }
     }

     // ------------------------------------------------------------------
     // Жизненный цикл
     // ------------------------------------------------------------------

     override fun onCreate() {
         super.onCreate()
         running = true
         wm = getSystemService(Context.WINDOW_SERVICE) as WindowManager
         prefs = getSharedPreferences("ovr", MODE_PRIVATE)
         ui = Handler(mainLooper)
         val th = HandlerThread("overlay-ocr")
         th.start()
         ocrThread = th
         ocrHandler = Handler(th.looper)
         ensureForeground(false)
         buildWindows()
     }

     override fun onBind(intent: Intent?): IBinder? = null

     override fun onDestroy() {
