             tv.setTextColor(txtTitle)
             tv.gravity = Gravity.CENTER
             tv.layoutParams = FrameLayout.LayoutParams(
                 FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT
             )
             f.addView(tv)
         }
         f.setOnClickListener { runCatching(onClick) }
         return f
     }

     private fun addRow(
         iconRes: Int?, leadGlyph: String?, title: String, sub: String?,
