     * с крошечным перерывом получаем «листание» без инерционного прыжка.
     */
    private fun swipe(x1: Float, y1: Float, x2: Float, y2: Float, durationMs: Long): Boolean {
        return try {
            val builder = GestureDescription.Builder()
            val seg = 2
            val segDur = durationMs / seg
            for (i in 0 until seg) {
                val fy = y1 + (y2 - y1) * i / seg
                val ty = y1 + (y2 - y1) * (i + 1) / seg
                val path = Path().apply {
                    moveTo(x1, fy)
                    lineTo(x1, ty)
                }
                builder.addStroke(
                    GestureDescription.StrokeDescription(path, segDur * i, segDur)
                )
            }
            dispatchGesture(builder.build(), null, null)
        } catch (e: Exception) {
            false
        }
    }

    private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

    private fun widthGuess(): Int = resources.displayMetrics.widthPixels.coerceAtLeast(1)

    companion object {
        private const val SCROLL_DURATION_MS = 900L
    }
}

