  */
 class OverlayService : Service() {

     companion object {
         const val ACTION_START = "app.yomikaioverlay.START"
         const val ACTION_SCAN_ONCE = "app.yomikaioverlay.SCAN_ONCE"
         const val ACTION_AUTO_READ = "app.yomikaioverlay.AUTO_READ"
         const val ACTION_PROJECTION = "app.yomikaioverlay.PROJECTION"
         const val ACTION_READ_TOGGLE = "app.yomikaioverlay.READ_TOGGLE"
         private const val NOTIF_ID = 101
         private const val CH_ID = "ocr_overlay"

         @Volatile
         var running = false
             private set

         fun startForegroundService(ctx: Context) {
             val i = Intent(ctx, OverlayService::class.java)
             i.action = ACTION_START
             try {
                 if (Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(i) else ctx.startService(i)
             } catch (e: Exception) {
                 ctx.startService(i)
             }
         }

         fun scanOnceNow(ctx: Context) {
             val i = Intent(ctx, OverlayService::class.java)
             i.action = ACTION_SCAN_ONCE
             try {
                 if (Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(i) else ctx.startService(i)
             } catch (e: Exception) {
                 ctx.startService(i)
             }
         }

         fun autoReadNow(ctx: Context) {
             val i = Intent(ctx, OverlayService::class.java)
             i.action = ACTION_AUTO_READ
             try {
                 if (Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(i) else ctx.startService(i)
             } catch (e: Exception) {
