     }

     private fun showMain(visible: Boolean) {
         ui.removeCallbacks(restoreBubble)
         hiddenSnooze = !visible
         mainRoot?.visibility = if (visible) View.VISIBLE else View.GONE
         if (!visible) ui.postDelayed(restoreBubble, 30_000)
         refreshFrame()
     }

     // --- Пузырь: тап = меню; тянуть = переместить ---
     private fun attachBubbleTouch(b: View) {
         val slop = ViewConfiguration.get(this).scaledTouchSlop
         var downX = 0f
         var downY = 0f
         var startX = 0
         var startY = 0
         var moved = false
         b.setOnTouchListener { v, ev ->
             val lp = mainLp ?: return@setOnTouchListener false
             when (ev.actionMasked) {
                 MotionEvent.ACTION_DOWN -> {
                     downX = ev.rawX
                     downY = ev.rawY
                     startX = lp.x
                     startY = lp.y
                     moved = false
                     true
                 }
                 MotionEvent.ACTION_MOVE -> {
                     val dx = ev.rawX - downX
                     val dy = ev.rawY - downY
                     if (!moved && (Math.abs(dx) > slop || Math.abs(dy) > slop)) moved = true
                     if (moved) {
                         val s = screenSize()
                         lp.x = clamp(startX + dx.toInt(), 0, s.x - v.width)
                         lp.y = clamp(startY + dy.toInt(), 0, s.y - v.height)
                         try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
                     }
                     true
                 }
                 MotionEvent.ACTION_UP -> {
                     if (!moved) toggleExpanded()
                     moved = false
                     v.performClick()
                     true
                 }
                 else -> false
             }
         }
     }

     private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

