     /** Дописать распознанный фрагмент в буфер авточтения и показать его снизу. */
     private fun appendRead(text: String) {
         if (readBuffer.isNotEmpty()) readBuffer.append('\n')
         readBuffer.append(text)
         if (readBuffer.length > 6000) readBuffer.delete(0, readBuffer.length - 6000)
         preview = readBuffer.toString().trim()
         previewText?.text = preview
         previewText?.post { previewText?.let { v -> v.scrollTo(0, v.layout?.height ?: 0) } }
     }

     private fun circle(sizeDp: Int, bgColor: Int): View {
         val v = View(this)
         v.background = rounded(bgColor, sizeDp / 2f)
         v.layoutParams = LinearLayout.LayoutParams(dp(sizeDp), dp(sizeDp))
         return v
     }

     private fun iconBtn(iconRes: Int?, glyph: String?, bgColor: Int, onClick: () -> Unit): FrameLayout {
         val f = FrameLayout(this)
         val size = dp(40f)
         f.layoutParams = LinearLayout.LayoutParams(size, size)
         f.background = rounded(bgColor, 20f)
         f.isClickable = true
         if (iconRes != null) {
             val iv = ImageView(this)
             iv.setImageResource(iconRes)
             val lp = FrameLayout.LayoutParams(dp(22f), dp(22f))
             lp.gravity = Gravity.CENTER
             iv.layoutParams = lp
             f.addView(iv)
         } else if (glyph != null) {
             val tv = TextView(this)
             tv.text = glyph
             tv.textSize = 16f
             tv.setTextColor(txtTitle)
             tv.gravity = Gravity.CENTER
             tv.layoutParams = FrameLayout.LayoutParams(
                 FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT
             )
             f.addView(tv)
         }
         f.setOnClickListener { runCatching(onClick) }
         return f
     }

     private fun addRow(
         iconRes: Int?, leadGlyph: String?, title: String, sub: String?,
         onTap: (() -> Unit)?, onLong: (() -> Unit)? = null,
         trailing: List<FrameLayout> = emptyList()
     ) {
         val card = panelCard ?: return
         val row = LinearLayout(this).apply {
             orientation = LinearLayout.HORIZONTAL
             gravity = Gravity.CENTER_VERTICAL
             setPadding(dp(6), dp(6), dp(6), dp(6))
         }
         row.addView(iconBtn(iconRes, leadGlyph, btnBg) {})
         val texts = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
         val tt = TextView(this).apply {
             text = title
             textSize = 15f
             setTextColor(txtTitle)
         }
         texts.addView(tt)
         if (sub != null) {
             val st = TextView(this).apply {
                 text = sub
                 textSize = 12f
                 setTextColor(txtSub)
             }
             texts.addView(st)
         }
         val tlp = LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f)
         tlp.setMargins(dp(12), 0, dp(6), 0)
         texts.layoutParams = tlp
         row.addView(texts)
         for (b in trailing) {
             val lp = b.layoutParams as LinearLayout.LayoutParams
             lp.setMargins(dp(6), 0, 0, 0)
             row.addView(b)
         }
         if (onTap != null) row.setOnClickListener { runCatching(onTap) }
         if (onLong != null) {
             row.setOnLongClickListener { runCatching(onLong); true }
         }
         card.addView(row)
     }

     private fun divider() {
         val card = panelCard ?: return
         val d = View(this)
         d.setBackgroundColor(Color.parseColor("#1AFFFFFF"))
         val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 1)
         lp.setMargins(dp(10), 0, dp(10), 0)
         d.layoutParams = lp
         card.addView(d)
     }

     private fun rebuildPanel() {
         val card = panelCard ?: return
         card.removeAllViews()
         updateStopButton()

         // превью распознанного текста / статус
         val pv = TextView(this).apply {
             val base = if (preview.isNotBlank()) preview else "Рамка: ${regionLabel()}. Тапни «OCR скан» или «Авточтение»."
             text = base
             textSize = 13f
             setTextColor(txtSub)
             setPadding(dp(10), dp(6), dp(10), dp(8))
             maxLines = 14
             isVerticalScrollBarEnabled = true
             movementMethod = android.text.method.ScrollingMovementMethod()
         }
         previewText = pv
         card.addView(pv)
         divider()

         // 1. OCR скан — разовый
         addRow(R.drawable.ic_scan, null, "OCR скан", "распознать и прочитать рамку",
             onTap = { scanOnceOrAsk() })

         // 2/3. Авточтение + Стоп
         if (autoReading) {
             addRow(R.drawable.ic_bars, null, "Авточтение: идёт…", "стоп — ниже; листает рамку и читает",
                 onTap = null)
             addRow(R.drawable.ic_stop, null, "Стоп чтения", null,
                 onTap = { stopAutoRead() })
         } else {
             addRow(R.drawable.ic_play, null, "Авточтение", "читает рамку и листает",
                 onTap = { startAutoReadOrAsk() })
         }

         // 4. Голос: ♀/♂ тембр, ≡ выбор конкретного голоса из списка + проба
         val gender = prefs.getString("gender", "female")
         val gsub = (if (gender == "male") "♂ мужской (тембр ниже)" else "♀ женский") + " · " + currentVoiceLabel()
         addRow(R.drawable.ic_bars, null, "Голос", gsub,
             onTap = null,
             trailing = listOf(
                 iconBtn(null, "♀", if (gender != "male") btnBgAccent else btnBg) {
                     setGender("female")
                 },
                 iconBtn(null, "♂", if (gender == "male") btnBgAccent else btnBg) {
                     setGender("male")
                 },
                 iconBtn(null, "≡", btnBg) {
                     openVoicePicker()
                 },
                 iconBtn(null, "⚙", btnBg) {
                     try {
                         val i = Intent("com.android.settings.TTS_SETTINGS")
                         i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                         startActivity(i)
                     } catch (e: Exception) {
                         Toast.makeText(this, "Настройки TTS недоступны", Toast.LENGTH_SHORT).show()
                     }
                 }
             )
         )

         // 5. Скорость
         val rate = prefs.getFloat("rate", 1.0f)
         val pct = Rates.percent(rate)
         addRow(null, "⏱", "Скорость: $pct%", "шаг 25%, диапазон 50…200%",
             onTap = null,
             trailing = listOf(
                 iconBtn(R.drawable.ic_remove, null, btnBg) { changeRate(-Rates.STEP) },
                 iconBtn(R.drawable.ic_add, null, btnBg) { changeRate(Rates.STEP) },
                 iconBtn(null, "1×", btnBg) { changeRate(1.0f - rate) }
             )
         )

         // 6. Движок: только онлайн (как в overlay-translator)
         val engId = engineId()
         val engSub = engineKeyHint() ?: Engines.subtitle(engId)
         addRow(R.drawable.ic_chip, null, "Движок: " + engineTitle(), engSub + ". Тап переключает",
             onTap = { switchEngine(Engines.next(engId)) })

         // 6.4 Перевод: OCR → RU → озвучка
         val trOn = prefs.getBoolean("translate", false)
         addRow(null, "⇄", if (trOn) "Перевод: ВКЛ" else "Перевод: выкл", "латиница → русский перед озвучкой (онлайн)",
             onTap = {
                 prefs.edit().putBoolean("translate", !trOn).apply()
                 Toast.makeText(this, if (!trOn) "Перевод включён" else "Перевод выключен", Toast.LENGTH_SHORT).show()
                 rebuildPanel()
             })

         // 6.5 Настройки
         addRow(null, "⚙", "Все настройки", "статус доступов, подсказки",
             onTap = {
                 try {
                     val i = Intent(this, MainActivity::class.java)
                     i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                     startActivity(i)
                 } catch (e: Exception) { }
             })

         // 7. Область
         addRow(R.drawable.ic_frame, null, "Область: ${regionLabel()}", "удерживай, чтобы потянуть рамку за ручки",
             onTap = { cycleRegionPreset() },
             onLong = { openRegionSelect() })

         divider()

         // 8. Панель вниз
         addRow(R.drawable.ic_chevron_down, null, "Панель вниз", "свернуть меню, пузырь останется",
             onTap = { setExpanded(false) })

         // 9. Скрыть пузырь
         addRow(R.drawable.ic_chevron_up, null, "Скрыть пузырь на 30 с", null,
             onTap = {
                 showMain(false)
                 ui.postDelayed({ showMain(true) }, 30_000)
             })

         // 10. Закрыть
