        style = Paint.Style.STROKE
        strokeWidth = dp(2.5f).toFloat()
        color = frameRed
        pathEffect = DashPathEffect(floatArrayOf(20f, 12f), 0f)
    }
    override fun onDraw(c: Canvas) {
