/** Кнопка «Стоп» у пузыря видна, пока идёт авточтение. */
private fun updateStopButton() {
    val btn = stopBtn ?: return
    val vis = if (autoReading) View.VISIBLE else View.GONE
    if (btn.visibility == vis) return
    val root = mainRoot
    val lp = mainLp
    val oldW = root?.width ?: 0
    btn.visibility = vis
    if (root == null || lp == null) return
    // Окно прижато к правому краю экрана: при появлении кнопки оно
    // становится шире и уезжало бы за экран. Сдвигаем x так, чтобы
    // правый край остался на месте и кнопка была видна.
    root.post {
        val newW = root.width
        if (oldW > 0 && newW > 0 && newW != oldW) {
            val s = screenSize()
            lp.x = clamp(lp.x - (newW - oldW), 0, (s.x - newW).coerceAtLeast(0))
            try { wm.updateViewLayout(root, lp) } catch (e: Exception) { }
        }
    }
}

