     private fun engineTitle(): String = Engines.title(engineId())

     /** Подсказка по ключу выбранного движка (или null, если всё ок). */
     private fun engineKeyHint(): String? = when (engineId()) {
         Engines.GOOGLE_AI -> if (EnginePrefs.googleApiKey(this).isBlank()) "нет ключа — задайте в настройках" else null
         Engines.OPENROUTER -> if (EnginePrefs.openrouterKey(this).isBlank()) "нет ключа — задайте в настройках" else null
         else -> null
