         row.addView(iconBtn(iconRes, leadGlyph, btnBg) {})
         val texts = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
         val tt = TextView(this).apply {
             text = title
             textSize = 15f
             setTextColor(txtTitle)
         }
         texts.addView(tt)
         if (sub != null) {
             val st = TextView(this).apply {
                 text = sub
                 textSize = 12f
                 setTextColor(txtSub)
             }
             texts.addView(st)
         }
         val tlp = LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f)
         tlp.setMargins(dp(12), 0, dp(6), 0)
         texts.layoutParams = tlp
         row.addView(texts)
         for (b in trailing) {
             val lp = b.layoutParams as LinearLayout.LayoutParams
             lp.setMargins(dp(6), 0, 0, 0)
             row.addView(b)
         }
         if (onTap != null) row.setOnClickListener { runCatching(onTap) }
         if (onLong != null) {
             row.setOnLongClickListener { runCatching(onLong); true }
         }
         card.addView(row)
