private fun setExpanded(v: Boolean) {
    expanded = v
    val scroll = panelScroll
    if (scroll != null) {
        scroll.visibility = if (v) View.VISIBLE else View.GONE
        if (v) {
            // Панель открывается под пузырём и растёт вниз. Высоту карточки
            // ограничиваем свободным местом до низа экрана, а содержимое
            // делаем прокручиваемым — иначе меню уезжает за экран.
            val s = screenSize()
            val top = (mainLp?.y ?: 0) + dp(56 + 10)
            scroll.maxHeightPx = (s.y - top - dp(16)).coerceAtLeast(dp(160))
        }
    }
    if (v) rebuildPanel()
    refreshFrame()
}

