    addRow(null, "⚙", "Все настройки", "статус доступов, подсказки",
        onTap = {
            try {
                val i = Intent(this, MainActivity::class.java)
                i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                startActivity(i)
            } catch (e: Exception) { }
        })

    // 7. Область
    addRow(R.drawable.ic_frame, null, "Область: ${regionLabel()}", "удерживай, чтобы потянуть рамку за ручки",
        onTap = { cycleRegionPreset() },
        onLong = { openRegionSelect() })

    divider()

    // 8. Панель вниз
    addRow(R.drawable.ic_chevron_down, null, "Панель вниз", "свернуть меню, пузырь останется",
        onTap = { setExpanded(false) })

    // 9. Скрыть пузырь
    addRow(R.drawable.ic_chevron_up, null, "Скрыть пузырь на 30 с", null,
        onTap = {
            showMain(false)
            ui.postDelayed({ showMain(true) }, 30_000)
        })

    // 10. Закрыть
    addRow(R.drawable.ic_close, null, "Закрыть", "удерживай, чтобы выключить сервис",
        onTap = { Toast.makeText(this, "Удерживайте «Закрыть», чтобы выключить", Toast.LENGTH_SHORT).show() },
        onLong = {
            stopSelf()
        })
}

