     private fun overlayLp(w: Int, h: Int, touchable: Boolean): WindowManager.LayoutParams {
         var flags = WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL or
             WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN
         flags = flags or if (touchable) {
             WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
         } else {
             WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE
         }
         val lp = WindowManager.LayoutParams(
             w, h,
             if (Build.VERSION.SDK_INT >= 26) WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
             else @Suppress("DEPRECATION") WindowManager.LayoutParams.TYPE_PHONE,
             flags,
             PixelFormat.TRANSLUCENT
         )
         lp.gravity = Gravity.TOP or Gravity.START
         return lp
     }

     private fun rounded(color: Int, rdp: Float) = GradientDrawable().apply {
         setColor(color)
         cornerRadius = dp(rdp).toFloat()
     }

     private fun buildWindows() {
         val s = screenSize()

         // Рамка OCR-области (ненажимаемая, прозрачная)
         frameView = RegionFrameView()
         frameLp = overlayLp(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, false)
         try { wm.addView(frameView, frameLp) } catch (e: Exception) { }

         // Пузырь + карточка панели в одном окне
         val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
         mainRoot = root
         mainLp = overlayLp(WindowManager.LayoutParams.WRAP_CONTENT, WindowManager.LayoutParams.WRAP_CONTENT, true).apply {
             x = s.x - dp(76)
             y = (s.y * 0.42f).toInt()
         }

         val bubble = BubbleView()
         bubbleView = bubble
         val bl = LinearLayout.LayoutParams(dp(56), dp(56))
         bubble.layoutParams = bl
         attachBubbleTouch(bubble)
         root.addView(bubble)

         val gap = View(this)
         gap.layoutParams = LinearLayout.LayoutParams(1, dp(10))
         root.addView(gap)

         val card = LinearLayout(this).apply {
             orientation = LinearLayout.VERTICAL
             background = rounded(cardBg, 18f)
         }
         val pad = dp(8)
         card.setPadding(pad, pad, pad, pad)
         panelCard = card
         val cardW = minOf(dp(356f), s.x - dp(24))
         val scroll = MaxScrollView(this).apply {
             visibility = View.GONE
             layoutParams = LinearLayout.LayoutParams(cardW, LinearLayout.LayoutParams.WRAP_CONTENT)
         }
         scroll.addView(
             card,
             FrameLayout.LayoutParams(
                 FrameLayout.LayoutParams.MATCH_PARENT,
                 FrameLayout.LayoutParams.WRAP_CONTENT
             )
         )
         panelScroll = scroll
         root.addView(scroll)

         try { wm.addView(root, mainLp) } catch (e: Exception) { }
     }

     private fun removeAllWindows() {
         hideStopButton()
+        closeMiniPanel()
         try { voiceWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         voiceWin = null
         try { selectRoot?.let { wm.removeView(it) } } catch (e: Exception) { }
         selectRoot = null
         try { mainRoot?.let { wm.removeView(it) } } catch (e: Exception) { }
         try { frameView?.let { wm.removeView(it) } } catch (e: Exception) { }
         mainRoot = null
         frameView = null
         panelScroll = null
         panelCard = null
     }

     private fun showMain(visible: Boolean) {
         ui.removeCallbacks(restoreBubble)
         hiddenSnooze = !visible
         mainRoot?.visibility = if (visible) View.VISIBLE else View.GONE
         if (!visible) ui.postDelayed(restoreBubble, 30_000)
         refreshFrame()
     }

     // --- Пузырь: тап = меню; тянуть = переместить ---
     private fun attachBubbleTouch(b: View) {
         val slop = ViewConfiguration.get(this).scaledTouchSlop
         var downX = 0f
         var downY = 0f
         var startX = 0
         var startY = 0
         var moved = false
         b.setOnTouchListener { v, ev ->
             val lp = mainLp ?: return@setOnTouchListener false
             when (ev.actionMasked) {
                 MotionEvent.ACTION_DOWN -> {
                     downX = ev.rawX
                     downY = ev.rawY
                     startX = lp.x
                     startY = lp.y
                     moved = false
                     true
                 }
                 MotionEvent.ACTION_MOVE -> {
                     val dx = ev.rawX - downX
                     val dy = ev.rawY - downY
                     if (!moved && (Math.abs(dx) > slop || Math.abs(dy) > slop)) moved = true
                     if (moved) {
                         val s = screenSize()
                         lp.x = clamp(startX + dx.toInt(), 0, s.x - v.width)
                         lp.y = clamp(startY + dy.toInt(), 0, s.y - v.height)
                         try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
                         placeStopButton()
                     }
                     true
                 }
                 MotionEvent.ACTION_UP -> {
                     if (!moved) toggleExpanded()
                     moved = false
                     v.performClick()
                     true
                 }
                 else -> false
             }
         }
     }

     private fun clamp(v: Int, lo: Int, hi: Int) = if (v < lo) lo else if (v > hi) hi else v

     // ------------------------------------------------------------------
     // Рамка OCR-области
     // ------------------------------------------------------------------

     private fun regionRatio(): Rect {
         val l = prefs.getFloat("reg_l", Region.DEFAULT_RATIOS[0])
         val t = prefs.getFloat("reg_t", Region.DEFAULT_RATIOS[1])
         val r = prefs.getFloat("reg_r", Region.DEFAULT_RATIOS[2])
         val b = prefs.getFloat("reg_b", Region.DEFAULT_RATIOS[3])
         val s = screenSize()
         val box = Region.boxFromRatios(l, t, r, b, s.x, s.y)
         return Rect(box.left, box.top, box.right, box.bottom)
     }

     private fun regionPreset(): String =
         Region.normalizePreset(prefs.getString("reg_preset", Region.PRESET_BOTTOM))

     private fun saveRegionRatio(rectPx: Rect, preset: String? = null) {
         val s = screenSize()
         val ratios = Region.ratiosOf(
             Region.Box(rectPx.left, rectPx.top, rectPx.right, rectPx.bottom), s.x, s.y,
         )
         prefs.edit()
             .putFloat("reg_l", ratios[0])
             .putFloat("reg_t", ratios[1])
             .putFloat("reg_r", ratios[2])
             .putFloat("reg_b", ratios[3])
             .putString("reg_preset", preset ?: Region.PRESET_CUSTOM)
             .apply()
         refreshFrame()
         rebuildPanel()
     }

     private fun regionLabel(): String = Region.label(regionPreset())

     private fun cycleRegionPreset() {
         val s = screenSize()
         val next = Region.nextPreset(regionPreset())
         val box = Region.rectFor(next, s.x, s.y)
         setPreset(next, box)
     }

     private fun setPreset(name: String, box: Region.Box) {
         prefs.edit().putString("reg_preset", name).apply()
         saveRegionRatio(Rect(box.left, box.top, box.right, box.bottom), name)
         frameView?.invalidate()
     }

     private fun refreshFrame() {
         frameView?.visibility =
             if (!hiddenSnooze && (expanded || autoReading)) View.VISIBLE else View.GONE
         frameView?.invalidate()
     }

     private inner class RegionFrameView : View(this@OverlayService) {
         private val p = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(2.5f).toFloat()
             color = frameRed
             pathEffect = DashPathEffect(floatArrayOf(20f, 12f), 0f)
         }
         override fun onDraw(c: Canvas) {
             val r = regionRatio()
             c.drawRect(
                 r.left + 2f, r.top + 2f, r.right - 2f, r.bottom - 2f, p
             )
         }
     }

     // --- Настройка рамки: удержание по строке «Область…» ---

     private fun openRegionSelect() {
         if (selectRoot != null) return
         setExpanded(false)
         val container = FrameLayout(this)
         val sel = RegionSelectView()
         container.addView(sel, FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT)
         val bar = LinearLayout(this).apply {
             orientation = LinearLayout.HORIZONTAL
             gravity = Gravity.CENTER
             setPadding(0, dp(8), 0, dp(16))
         }
         val btnLp = LinearLayout.LayoutParams(0, dp(48), 1f).apply { setMargins(dp(8), 0, dp(8), 0) }
         fun mkBtn(t: String): Button {
             val b = Button(this)
             b.text = t
             b.setTextColor(txtTitle)
             b.background = rounded(btnBg, 12f)
             b.layoutParams = btnLp
             bar.addView(b)
             return b
         }
         mkBtn("Готово").setOnClickListener {
             saveRegionRatio(sel.currentRect())
             closeRegionSelect()
             setExpanded(true)
         }
         mkBtn("Сброс").setOnClickListener {
             val s = screenSize()
             sel.setRect(Region.rectFor(Region.PRESET_BOTTOM, s.x, s.y))
         }
         mkBtn("Отмена").setOnClickListener {
             closeRegionSelect()
             setExpanded(true)
         }
         val bl = FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.WRAP_CONTENT)
         bl.gravity = Gravity.BOTTOM
         container.addView(bar, bl)
         val lp = overlayLp(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, true)
         try { wm.addView(container, lp) } catch (e: Exception) { }
         selectRoot = container
         refreshFrame()
     }

     private fun closeRegionSelect() {
         try { selectRoot?.let { wm.removeView(it) } } catch (e: Exception) { }
         selectRoot = null
         refreshFrame()
     }

     private inner class RegionSelectView : View(this@OverlayService) {
         private var box: Region.Box = regionRatio().let {
             Region.Box(it.left, it.top, it.right, it.bottom)
         }
         private val zone = dp(48)
         private val minSide = dp(80)
         private val border = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(3).toFloat()
             color = frameRed
         }
         private val fill = Paint().apply {
             style = Paint.Style.FILL
             color = Color.parseColor("#33FFFFFF")
         }
         private val handlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.WHITE }

         private var mode = 0 // 1..8: стороны/угол; -6 move
         private var lastX = 0f
         private var lastY = 0f

         fun currentRect(): Rect = Rect(box.left, box.top, box.right, box.bottom)
         fun setRect(r: Region.Box) { box = r; invalidate() }

         override fun onDraw(c: Canvas) {
             // затемнение снаружи
             val w = width
             val h = height
             c.drawRect(0f, 0f, w.toFloat(), box.top.toFloat(), fill)
             c.drawRect(0f, box.bottom.toFloat(), w.toFloat(), h.toFloat(), fill)
             c.drawRect(0f, box.top.toFloat(), box.left.toFloat(), box.bottom.toFloat(), fill)
             c.drawRect(box.right.toFloat(), box.top.toFloat(), w.toFloat(), box.bottom.toFloat(), fill)
             c.drawRect(Rect(box.left, box.top, box.right, box.bottom), border)
             // четыре прямоугольника-ручки по серединам сторон + уголок справа-снизу
             val hw = dp(44f).toFloat()
             val hh = dp(12f).toFloat()
             val cx = (box.left + box.right) / 2f
             val cy = (box.top + box.bottom) / 2f
             val tops = arrayOf(
                 floatArrayOf(cx, box.top.toFloat()),
                 floatArrayOf(cx, box.bottom.toFloat())
             )
             for (t in tops) c.drawRoundRect(t[0] - hw / 2, t[1] - hh / 2, t[0] + hw / 2, t[1] + hh / 2, 8f, 8f, handlePaint)
             val sides = arrayOf(
                 floatArrayOf(box.left.toFloat(), cy),
                 floatArrayOf(box.right.toFloat(), cy)
             )
             for (t in sides) c.drawRoundRect(t[0] - hh / 2, t[1] - hw / 2, t[0] + hh / 2, t[1] + hw / 2, 8f, 8f, handlePaint)
             c.drawCircle(box.right.toFloat(), box.bottom.toFloat(), dp(16f).toFloat(), handlePaint)
         }

         override fun onTouchEvent(ev: MotionEvent): Boolean {
             when (ev.actionMasked) {
                 MotionEvent.ACTION_DOWN -> {
                     lastX = ev.x
                     lastY = ev.y
                     mode = zoneFor(ev.x.toInt(), ev.y.toInt())
                     return true
                 }
                 MotionEvent.ACTION_MOVE -> {
                     val s = screenSize()
                     val dx = (ev.x - lastX).toInt()
                     val dy = (ev.y - lastY).toInt()
                     lastX = ev.x
                     lastY = ev.y
                     applyDrag(s, dx, dy)
                     invalidate()
                     return true
                 }
                 MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                     mode = 0
                     return true
                 }
             }
             return super.onTouchEvent(ev)
         }

         private fun zoneFor(x: Int, y: Int): Int {
             val nearL = Math.abs(x - box.left) <= zone
             val nearR = Math.abs(x - box.right) <= zone
             val nearT = Math.abs(y - box.top) <= zone
             val nearB = Math.abs(y - box.bottom) <= zone
             // углы имеют приоритет
             if (nearL && nearT) return 1
             if (nearR && nearT) return 2
             if (nearL && nearB) return 3
             if (nearR && nearB) return 4
             if (nearL) return 5
             if (nearR) return 6
             if (nearT) return 7
             if (nearB) return 8
             return if (
                 x > box.left && x < box.right && y > box.top && y < box.bottom
             ) -6 else 0
         }

         /**
          * Двигает соответствующую грань и приводит рамку к экрану: инверсия
          * сторон и выезд за границы экрана невозможны (см. [Region.clamp]).
          */
         private fun applyDrag(s: Point, dx: Int, dy: Int) {
             var l = box.left
             var t = box.top
             var r = box.right
             var b = box.bottom
             when (mode) {
                 -6 -> { l += dx; r += dx; t += dy; b += dy }
                 1 -> { l += dx; t += dy }
                 2 -> { r += dx; t += dy }
                 3 -> { l += dx; b += dy }
                 4 -> { r += dx; b += dy }
                 5 -> l += dx
                 6 -> r += dx
                 7 -> t += dy
                 8 -> b += dy
             }
             box = Region.clamp(Region.Box(l, t, r, b), s.x, s.y, minSide, minSide)
         }
     }

