         container.setOnClickListener { closeVoicePicker() }
         card.setOnClickListener { } // гасим клики по карточке
         val lp = overlayLp(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT, true)
         try { wm.addView(container, lp) } catch (e: Exception) { }
         voiceWin = container
         rebuildPanel()
     }

     private fun voicesNoneYet(list: LinearLayout): Boolean {
         val t = tts ?: return true
         return try { !ttsReady || t.voices.isNullOrEmpty() } catch (e: Exception) { true }
     }

     private fun closeVoicePicker() {
         try { voiceWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         voiceWin = null
         rebuildPanel()
     }

     /** Пробная фраза: без пометки «идёт чтение» — просто прослушать голос. */
     private fun speakNowSilentPreview(phrase: String) {
         if (ttsBackend() == "edge") {
             speakEdge(phrase)
             return
         }
         val t = tts
         if (t == null || !ttsReady) {
             ui.postDelayed({ speakNowSilentPreview(phrase) }, 600)
             return
         }
         try {
             t.language = pickLocale(phrase)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
             t.speak(phrase, TextToSpeech.QUEUE_FLUSH, android.os.Bundle(), "ovr-preview")
         } catch (e: Exception) { }
     }

     private fun ttsBackend(): String = prefs.getString("tts_backend", "edge") ?: "edge"

     /** Edge-голос: явный выбор из списка, иначе по тембру ♀/♂. */
     private fun edgeVoiceName(): String {
         val custom = prefs.getString("edge_voice", "") ?: ""
         if (custom.isNotBlank()) return custom
         return if (prefs.getString("gender", "female") == "male") "ru-RU-DmitryNeural" else "ru-RU-SvetlanaNeural"
     }

     private fun pickLocale(text: String): Locale {
         var cyr = 0
         var lat = 0
         for (ch in text) {
             if (ch in 'А'..'я' || ch == 'Ё' || ch == 'ё') cyr++
             else if (ch in 'A'..'Z' || ch in 'a'..'z') lat++
         }
         return if (cyr >= lat) Locale("ru", "RU") else Locale.ENGLISH
     }

     private fun speak(text: String) {
         if (text.isBlank()) return
         ensureTts()
         val t = tts
         if (t == null || !ttsReady) {
             // Системный TTS инициализируется асинхронно: без ожидания реплика
             // терялась молча (speak до onInit не проигрывается).
             ui.postDelayed({ speakNow(text) }, 650)
             return
         }
         speakNow(text)
     }

     private fun speakNow(text: String) {
         if (ttsBackend() == "edge") {
             speakEdge(text)
             return
         }
         speakNowSystem(text)
     }

     private fun speakNowSystem(text: String) {
         val t = tts
         if (t == null || !ttsReady) {
             // не готов — вернёмся через speak(), он повторит
             ui.postDelayed({ speak(text) }, 650)
             return
         }
         try {
             t.language = pickLocale(text)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
             speaking = true
             val params = android.os.Bundle()
             t.speak(text, TextToSpeech.QUEUE_FLUSH, params, "ovr-utterance")
         } catch (e: Exception) {
             speaking = false
         }
     }

     /** Синтез сетевым голосом Edge: тексты уходят в Microsoft, кадры — никогда. */
     private fun speakEdge(text: String) {
         speaking = true
         val voice = edgeVoiceName()
         val rate = prefs.getFloat("rate", 1.0f)
         val pitch = if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f
         val gen = speakGen // стоп/onDestroy между синтезом и игрой — отменит проигрывание
         Thread {
             var ok = false
             try {
                 val ratePercent = ((rate - 1f) * 100f).roundToInt()
                 val pitchHz = ((pitch - 1f) * 200f).roundToInt()
                 val file = runBlocking {
                     EdgeTts.synthesizeToFile(applicationContext, text, voice, ratePercent, pitchHz)
                 }
                 if (file != null) {
                     ok = true
                     ui.post { playEdgeAudio(file, gen) }
                 }
             } catch (e: Exception) {
                 android.util.Log.w("Edge", "speakEdge: ${e.message}")
             }
             if (!ok) {
                 // нет сети/сервер недоступен → фолбэк на системный TTS
                 ui.post { speakNowSystem(text) }
             }
         }.start()
     }

     private fun playEdgeAudio(file: java.io.File, gen: Long) {
         if (gen != speakGen) {
             // чтение остановили, пока шёл синтез — файл не нужен
             runCatching { file.delete() }
             speaking = false
             return
         }
         try {
             runCatching { mediaPlayer?.release() }
             val mp = MediaPlayer()
             mediaPlayer = mp
             mp.setAudioAttributes(
                 AudioAttributes.Builder()
                     .setUsage(AudioAttributes.USAGE_MEDIA)
                     .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                     .build(),
             )
             mp.setDataSource(file.absolutePath)
             mp.setOnErrorListener { _, _, _ ->
                 runCatching { file.delete() }
                 speaking = false
                 true
             }
             mp.setOnPreparedListener { media ->
                 media.start()
             }
             mp.setOnCompletionListener { done ->
                 runCatching { done.release() }
                 mediaPlayer = null
                 runCatching { file.delete() }
                 speaking = false
                 if (autoReading) {
                     ui.postDelayed({ if (autoReading) scrollAndContinue() }, 350)
                 }
             }
             mp.prepareAsync()
         } catch (e: Exception) {
             android.util.Log.w("Edge", "playback: ${e.message}")
             runCatching { file.delete() }
             speaking = false
         }
     }

     // ------------------------------------------------------------------
     // Сценарии чтения
     // ------------------------------------------------------------------

     private fun scanOnce() {
         preview = "Сканирую…"
         previewText?.text = preview
         notifyStatus("Сканирую рамку…")
         refreshFrame()
         ocrScan { text ->
             if (text.isBlank()) {
                 if (!preview.startsWith("⚠")) preview = "Текст не найден в рамке"
                 previewText?.text = preview
                 notifyStatus(preview)
                 return@ocrScan
             }
             preview = text
             previewText?.text = preview
             setExpanded(true)
             notifyStatus(text) // распознанное текстом видно в шторке
             speak(text)
         }
     }

     private fun startAutoRead() {
         if (autoReading) return
         autoReading = true
         lastText = ""
         repeatCount = 0
         readBuffer.setLength(0)
         setExpanded(true)
         rebuildPanel()
         showStopButton()
         refreshFrame()
         try {
             val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
             @Suppress("DEPRECATION")
             wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "ovr:read")
             wakeLock?.acquire(30 * 60 * 1000L)
         } catch (e: Exception) { }
         autoStep()
     }

     fun stopAutoRead() {
         autoReading = false
         hideStopButton()
         speakGen++ // прерываем и запрещаем доигрывать уже синтезированное
         try { tts?.stop() } catch (e: Exception) { }
         runCatching { mediaPlayer?.let { if (it.isPlaying) it.stop(); it.release() } }
         mediaPlayer = null
         speaking = false
         rebuildPanel()
         refreshFrame()
         notifyStatus(if (preview.isNotBlank()) preview else null)
     }

     /** Столько раз подряд разрешаем «пустой/тот же текст» перед авто-стопом. */
     private val maxRepeats = 6

     private fun autoStep() {
         if (!autoReading) return
         ocrScan { text ->
             if (!autoReading) return@ocrScan
             val norm = norm(text)
             if (norm.isBlank() || norm == lastText) {
                 repeatCount++
                 if (repeatCount >= maxRepeats) {
                     // Страница не меняется: конец текста или выключена
                     // прокрутка. Раньше цикл крутился вечно.
                     stopAutoRead()
                     preview = "⚠ Авточтение остановлено: текст в рамке не меняется"
                     previewText?.text = preview
                     notifyStatus(preview)
                     return@ocrScan
                 }
                 scrollAndContinue()
                 return@ocrScan
             }
             repeatCount = 0
             lastText = norm
             appendRead(text)
             notifyStatus(text)
             speak(text)
             // продолжение — из onDone говорилки
         }
     }

     private fun scrollAndContinue() {
         val r = regionRatio()
         val svc = ScrollAccessibilityService.instance
         if (svc != null) {
             try { svc.swipeForward(r.left, r.top, r.right, r.bottom) } catch (e: Exception) { }
             ui.postDelayed({ if (autoReading) autoStep() }, 1500)
         } else {
             // Автопрокрутка выключена: ждём и читаем то же место снова (так видно,
             // что службу спецвозможностей нужно включить — есть подсказка в меню).
             ui.postDelayed({
                 if (!autoReading) return@postDelayed
                 preview = "⚠ Автопрокрутка выключена — включите «Yomikai Оверлей — прокрутка» в спец. возможностях"
                 previewText?.text = preview
                 lastText = "" // пусть перечитает после включения/ручной прокрутки
                 ui.postDelayed({ if (autoReading) autoStep() }, 2500)
             }, 600)
         }
     }

     private fun norm(s: String) = s.lowercase().replace("\\s+".toRegex(), " ").trim()

     override fun onConfigurationChanged(newConfig: Configuration) {
         super.onConfigurationChanged(newConfig)
         refreshFrame()
         // После поворота пузырь мог оказаться за пределами нового экрана.
         val lp = mainLp ?: return
         val s = screenSize()
         val vw = mainRoot?.width?.takeIf { it > 0 } ?: dp(56)
         val vh = mainRoot?.height?.takeIf { it > 0 } ?: dp(56)
         val nx = clamp(lp.x, 0, (s.x - vw).coerceAtLeast(0))
         val ny = clamp(lp.y, 0, (s.y - vh).coerceAtLeast(0))
         if (nx != lp.x || ny != lp.y) {
             lp.x = nx
             lp.y = ny
             try { wm.updateViewLayout(mainRoot, lp) } catch (e: Exception) { }
         }
         placeStopButton()
     }
 }

