     private fun openRegionSelect() {
         if (selectRoot != null) return
         setExpanded(false)
         val container = FrameLayout(this)
         val sel = RegionSelectView()
         container.addView(sel, FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT)
         val bar = LinearLayout(this).apply {
             orientation = LinearLayout.HORIZONTAL
             gravity = Gravity.CENTER
             setPadding(0, dp(8), 0, dp(16))
         }
         val btnLp = LinearLayout.LayoutParams(0, dp(48), 1f).apply { setMargins(dp(8), 0, dp(8), 0) }
         fun mkBtn(t: String): Button {
             val b = Button(this)
             b.text = t
             b.setTextColor(txtTitle)
             b.background = rounded(btnBg, 12f)
             b.layoutParams = btnLp
             bar.addView(b)
             return b
         }
         mkBtn("Готово").setOnClickListener {
             saveRegionRatio(sel.currentRect())
             closeRegionSelect()
             setExpanded(true)
         }
         mkBtn("Сброс").setOnClickListener {
             val s = screenSize()
             sel.setRect(Region.rectFor(Region.PRESET_BOTTOM, s.x, s.y))
