     private fun setExpanded(v: Boolean) {
         expanded = v
         if (!v) closeMiniPanel()
         val scroll = panelScroll
         if (scroll != null) {
             scroll.visibility = if (v) View.VISIBLE else View.GONE
             if (v) {
                 // Панель открывается под пузырём и растёт вниз. Высоту карточки
                 // ограничиваем свободным местом до низа экрана, а содержимое
                 // делаем прокручиваемым — иначе меню уезжает за экран.
                 val s = screenSize()
                 val top = (mainLp?.y ?: 0) + dp(56 + 10)
                 scroll.maxHeightPx = (s.y - top - dp(16)).coerceAtLeast(dp(160))
             }
         }
         if (v) rebuildPanel()
         refreshFrame()
     }

     private fun toggleExpanded() = setExpanded(!expanded)

     /** Круглая кнопка «Стоп» в отдельном окне — видна только во время авточтения. */
     private fun showStopButton() {
         if (stopWin != null) { placeStopButton(); return }
         val size = dp(56)
         val v = FrameLayout(this).apply {
             background = rounded(Color.parseColor("#E6B3261E"), 28f)
             setOnClickListener { stopAutoRead() }
         }
         v.addView(
             TextView(this).apply {
                 text = "■"
                 textSize = 24f
                 setTextColor(Color.WHITE)
                 gravity = Gravity.CENTER
             },
             FrameLayout.LayoutParams(
                 FrameLayout.LayoutParams.MATCH_PARENT,
                 FrameLayout.LayoutParams.MATCH_PARENT
             )
         )
         val lp = overlayLp(size, size, true)
         stopWin = v
         stopLp = lp
         try {
             wm.addView(v, lp)
         } catch (e: Exception) {
             stopWin = null
             stopLp = null
             return
         }
         placeStopButton()
     }

     private fun placeStopButton() {
         val v = stopWin ?: return
         val lp = stopLp ?: return
         val size = dp(56)
         val s = screenSize()
         val base = mainLp
         // Ставим кнопку слева от пузыря и держим целиком в пределах экрана.
         lp.x = ((base?.x ?: (s.x - dp(76))) - size - dp(8))
             .coerceIn(0, (s.x - size).coerceAtLeast(0))
         lp.y = (base?.y ?: (s.y * 0.42f).toInt())
             .coerceIn(0, (s.y - size).coerceAtLeast(0))
         try { wm.updateViewLayout(v, lp) } catch (e: Exception) { }
     }

