     private fun closeVoicePicker() {
         try { voiceWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         voiceWin = null
         rebuildPanel()
     }

     /** Пробная фраза: без пометки «идёт чтение» — просто прослушать голос. */
     private fun speakNowSilentPreview(phrase: String) {
         if (ttsBackend() == "edge") {
             speakEdge(phrase)
             return
         }
         val t = tts
         if (t == null || !ttsReady) {
             ui.postDelayed({ speakNowSilentPreview(phrase) }, 600)
             return
         }
         try {
             t.language = pickLocale(phrase)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
             t.speak(phrase, TextToSpeech.QUEUE_FLUSH, android.os.Bundle(), "ovr-preview")
         } catch (e: Exception) { }
     }

     private fun ttsBackend(): String = prefs.getString("tts_backend", "edge") ?: "edge"

     /** Edge-голос: явный выбор из списка, иначе по тембру ♀/♂. */
     private fun edgeVoiceName(): String {
         val custom = prefs.getString("edge_voice", "") ?: ""
         if (custom.isNotBlank()) return custom
         return if (prefs.getString("gender", "female") == "male") "ru-RU-DmitryNeural" else "ru-RU-SvetlanaNeural"
     }

     private fun pickLocale(text: String): Locale {
         var cyr = 0
         var lat = 0
         for (ch in text) {
             if (ch in 'А'..'я' || ch == 'Ё' || ch == 'ё') cyr++
             else if (ch in 'A'..'Z' || ch in 'a'..'z') lat++
         }
         return if (cyr >= lat) Locale("ru", "RU") else Locale.ENGLISH
     }

     private fun speak(text: String) {
         if (text.isBlank()) return
         ensureTts()
         val t = tts
         if (t == null || !ttsReady) {
             // Системный TTS инициализируется асинхронно: без ожидания реплика
             // терялась молча (speak до onInit не проигрывается).
             ui.postDelayed({ speakNow(text) }, 650)
             return
         }
         speakNow(text)
     }

     private fun speakNow(text: String) {
         if (ttsBackend() == "edge") {
             speakEdge(text)
             return
         }
         speakNowSystem(text)
     }

     private fun speakNowSystem(text: String) {
         val t = tts
         if (t == null || !ttsReady) {
             // не готов — вернёмся через speak(), он повторит
             ui.postDelayed({ speak(text) }, 650)
             return
         }
         try {
             t.language = pickLocale(text)
             applyVoicePref(t)
             t.setSpeechRate(prefs.getFloat("rate", 1.0f))
             t.setPitch(if (prefs.getString("gender", "female") == "male") 0.82f else 1.15f)
