     private inner class RegionSelectView : View(this@OverlayService) {
         private var box: Region.Box = regionRatio().let {
             Region.Box(it.left, it.top, it.right, it.bottom)
         }
         private val zone = dp(48)
         private val minSide = dp(80)
         private val border = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(3).toFloat()
             color = frameRed
         }
         private val fill = Paint().apply {
             style = Paint.Style.FILL
             color = Color.parseColor("#33FFFFFF")
         }
         private val handlePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.WHITE }

         private var mode = 0 // 1..8: стороны/угол; -6 move
         private var lastX = 0f
         private var lastY = 0f

         fun currentRect(): Rect = Rect(box.left, box.top, box.right, box.bottom)
         fun setRect(r: Region.Box) { box = r; invalidate() }

         override fun onDraw(c: Canvas) {
             // затемнение снаружи
             val w = width
             val h = height
             c.drawRect(0f, 0f, w.toFloat(), box.top.toFloat(), fill)
             c.drawRect(0f, box.bottom.toFloat(), w.toFloat(), h.toFloat(), fill)
             c.drawRect(0f, box.top.toFloat(), box.left.toFloat(), box.bottom.toFloat(), fill)
             c.drawRect(box.right.toFloat(), box.top.toFloat(), w.toFloat(), box.bottom.toFloat(), fill)
             c.drawRect(Rect(box.left, box.top, box.right, box.bottom), border)
             // четыре прямоугольника-ручки по серединам сторон + уголок справа-снизу
             val hw = dp(44f).toFloat()
             val hh = dp(12f).toFloat()
             val cx = (box.left + box.right) / 2f
             val cy = (box.top + box.bottom) / 2f
             val tops = arrayOf(
                 floatArrayOf(cx, box.top.toFloat()),
                 floatArrayOf(cx, box.bottom.toFloat())
             )
             for (t in tops) c.drawRoundRect(t[0] - hw / 2, t[1] - hh / 2, t[0] + hw / 2, t[1] + hh / 2, 8f, 8f, handlePaint)
             val sides = arrayOf(
                 floatArrayOf(box.left.toFloat(), cy),
                 floatArrayOf(box.right.toFloat(), cy)
             )
             for (t in sides) c.drawRoundRect(t[0] - hh / 2, t[1] - hw / 2, t[0] + hh / 2, t[1] + hw / 2, 8f, 8f, handlePaint)
             c.drawCircle(box.right.toFloat(), box.bottom.toFloat(), dp(16f).toFloat(), handlePaint)
         }

         override fun onTouchEvent(ev: MotionEvent): Boolean {
             when (ev.actionMasked) {
                 MotionEvent.ACTION_DOWN -> {
                     lastX = ev.x
                     lastY = ev.y
                     mode = zoneFor(ev.x.toInt(), ev.y.toInt())
                     return true
                 }
                 MotionEvent.ACTION_MOVE -> {
                     val s = screenSize()
                     val dx = (ev.x - lastX).toInt()
                     val dy = (ev.y - lastY).toInt()
                     lastX = ev.x
                     lastY = ev.y
                     applyDrag(s, dx, dy)
                     invalidate()
                     return true
                 }
                 MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                     mode = 0
                     return true
                 }
             }
             return super.onTouchEvent(ev)
         }

         private fun zoneFor(x: Int, y: Int): Int {
             val nearL = Math.abs(x - box.left) <= zone
             val nearR = Math.abs(x - box.right) <= zone
             val nearT = Math.abs(y - box.top) <= zone
             val nearB = Math.abs(y - box.bottom) <= zone
             // углы имеют приоритет
             if (nearL && nearT) return 1
             if (nearR && nearT) return 2
             if (nearL && nearB) return 3
             if (nearR && nearB) return 4
             if (nearL) return 5
             if (nearR) return 6
             if (nearT) return 7
             if (nearB) return 8
             return if (
                 x > box.left && x < box.right && y > box.top && y < box.bottom
             ) -6 else 0
         }

         /**
          * Двигает соответствующую грань и приводит рамку к экрану: инверсия
          * сторон и выезд за границы экрана невозможны (см. [Region.clamp]).
          */
         private fun applyDrag(s: Point, dx: Int, dy: Int) {
             var l = box.left
             var t = box.top
             var r = box.right
             var b = box.bottom
             when (mode) {
                 -6 -> { l += dx; r += dx; t += dy; b += dy }
                 1 -> { l += dx; t += dy }
                 2 -> { r += dx; t += dy }
                 3 -> { l += dx; b += dy }
                 4 -> { r += dx; b += dy }
                 5 -> l += dx
                 6 -> r += dx
                 7 -> t += dy
                 8 -> b += dy
             }
             box = Region.clamp(Region.Box(l, t, r, b), s.x, s.y, minSide, minSide)
         }
     }

