     private inner class BubbleView : View(this@OverlayService) {
         private val bgPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.FILL
             color = Color.parseColor("#E6262A34")
         }
         private val dash = Paint(Paint.ANTI_ALIAS_FLAG).apply {
             style = Paint.Style.STROKE
             strokeWidth = dp(3f).toFloat()
             color = frameRed
             pathEffect = DashPathEffect(floatArrayOf(16f, 9f), 0f)
         }
         override fun onDraw(c: Canvas) {
             val w = width.toFloat()
             val h = height.toFloat()
             val rad = minOf(w, h) / 2f
             c.drawRoundRect(0f, 0f, w, h, rad, rad, bgPaint)
             val inset = dp(7f).toFloat()
             c.drawRoundRect(inset, inset, w - inset, h - inset, rad - inset, rad - inset, dash)
         }
     }

