```kotlin
package app.yomikaioverlay.ot

import android.graphics.Rect

/** Направлений чтения распознанных блоков текста. */
object ReadingOrder {
    const val AUTO = "auto"
    const val LTR = "ltr"          // слева → направо
    const val RTL = "rtl"          // справа → налево
    const val VERTICAL = "vertical" // колонки справа → налево, сверху вниз (манга)
    const val BOTTOM_UP = "bottom_up"

    val MODES = listOf(AUTO, LTR, RTL, VERTICAL, BOTTOM_UP)
    const val DEFAULT = AUTO

    fun normalize(mode: String?): String = if (mode in MODES) mode else DEFAULT

    fun label(mode: String?): String = when (normalize(mode)) {
        AUTO -> "Как распознано"
        LTR -> "→ слева направо"
        RTL -> "← справа налево"
        VERTICAL -> "↓ вертикально"
        BOTTOM_UP -> "↑ снизу вверх"
        else -> "Как распознано"
    }

    /** Порядок чтения блоков 1..N по выбранному направлению. */
    fun order(rects: List<Rect>, mode: String?): List<Rect> {
        if (rects.size < 2) return rects
        return when (normalize(mode)) {
            AUTO -> rects
            LTR -> rows(rects).flatMap { it.sortedBy { r -> r.left } }
            RTL -> rows(rects).flatMap { it.sortedByDescending { r -> r.right } }
            BOTTOM_UP -> rows(rects).reversed().flatMap { it.sortedBy { r -> r.left } }
            VERTICAL -> columns(rects).sortedByDescending { c -> c.first().centerX() }
                .flatMap { it.sortedBy { r -> r.top } }
            else -> rects
        }
    }

    /** Делит блоки на строки по вертикальному пересечению. */
    fun rows(rects: List<Rect>): List<List<Rect>> =
        groupByBand(rects, horizontal = true)

    /** Делит блоки на колонки по горизонтальному пересечению. */
    fun columns(rects: List<Rect>): List<List<Rect>> =
        groupByBand(rects, horizontal = false)

    private fun groupByBand(rects: List<Rect>, horizontal: Boolean): List<List<Rect>> {
        val sorted = if (horizontal) rects.sortedBy { it.top } else rects.sortedBy { it.left }
        val bands = mutableListOf<MutableList<Rect>>()
        for (r in sorted) {
            val anchor = bands.firstOrNull { members ->
                members.first().let { a -> overlap(a, r, horizontal) }
            }
            if (anchor != null) anchor.add(r) else bands.add(mutableListOf(r))
        }
        return bands
    }

    private fun overlap(a: Rect, b: Rect, horizontal: Boolean): Boolean {
        val aS = if (horizontal) a.top else a.left
        val aE = if (horizontal) a.bottom else a.right
        val bS = if (horizontal) b.top else b.left
        val bE = if (horizontal) b.bottom else b.right
        val inter = minOf(aE, bE) - maxOf(aS, bS)
        val minLen = minOf(aE - aS, bE - bS)
        if (minLen <= 0) return false
        return inter.toFloat() / minLen >= 0.4f
    }
}
```

Note: `band.first().let` usage; `rows` grouping uses anchor compare. For columns, the anchor is leftmost block; blocks overlapping it horizontally in the same column.

Hmm, the greedy approach might lump whole page into one row if blocks overlap heavily. For text blocks with typical spacing it's fine.

Vertical order: columns sorted by centerX descending (right column first), each column top→bottom.

