```kotlin
package app.yomikaioverlay.ot

import android.graphics.Bitmap
import android.graphics.Rect
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.Text
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.TextRecognizerOptions
import kotlinx.coroutines.tasks.await

/** Data class */
data class LayoutBlock(val text: String, val rect: Rect)

/**
 * Гибрид: ML Kit даёт координаты блоков текста для пометки рамками и
 * порядка чтения, а сам текст для озвучки/перевода — как раньше (онлайн).
 * Если Play Services / ML-модели недоступны — isAvailable=false, всё
 * работает как раньше (без рамок и номеров).
 */
class LayoutOcr {
    private var recognizer: TextRecognition? = null
    private var failure = false

    init {
        try {
            recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)
        } catch (e: Throwable) {
            failure = true
        }
    }

    val isAvailable: Boolean get() = recognizer != null

    suspend fun blocks(bitmap: Bitmap): List<LayoutBlock> {
        val rec = recognizer ?: return emptyList()
        return try {
            val img = InputImage.fromBitmap(bitmap, 0)
            val text: Text = rec.process(img).await()
            text.textBlocks.mapNotNull { b ->
                val box = b.boundingBox ?: return@mapNotNull null
                LayoutBlock(b.text, box)
            }
        } catch (e: Throwable) {
            failure = true
            recognizer = null
            emptyList()
        }
    }

    fun close() {
        try { recognizer?.close() } catch (e: Throwable) { }
        recognizer = null
    }
}
