Hmm but `layoutRects` variable declared in else branch scope. Declare `var layoutRects: List<Rect> = emptyList()` before try, assign in else. ui.post closure captures it.

computeLayout helper:
```kotlin
private fun computeLayout(bmp: Bitmap): List<Rect> {
    if (layoutOcr == null) {
        layoutOcr = try { LayoutOcr() } catch (e: Throwable) { null }
    }
    val lo = layoutOcr
    if (lo == null || !lo.isAvailable) return emptyList()
    val r = regionRatio()
    val w = bmp.width.toFloat().coerceAtLeast(1f)
    val h = bmp.height.toFloat().coerceAtLeast(1f)
    val mapped = try {
        lo.blocks(bmp).map { b ->
            val bx = b.rect
            Rect(
                r.left + (bx.left / w * (r.right - r.left)).toInt(),
                r.top + (bx.top / h * (r.bottom - r.top)).toInt(),
                r.left + (bx.right / w * (r.right - r.left)).toInt(),
                r.top + (bx.bottom / h * (r.bottom - r.top)).toInt()
            )
        }
    } catch (e: Throwable) { emptyList() }
    return ReadingOrder.order(mapped, readOrderMode())
}
```

