             stopWin = null
             stopLp = null
             return
         }
         placeStopButton()
     }

     private fun placeStopButton() {
         val v = stopWin ?: return
         val lp = stopLp ?: return
         val size = dp(56)
         val s = screenSize()
         val base = mainLp
         // Ставим кнопку слева от пузыря и держим целиком в пределах экрана.
         lp.x = ((base?.x ?: (s.x - dp(76))) - size - dp(8))
             .coerceIn(0, (s.x - size).coerceAtLeast(0))
         lp.y = (base?.y ?: (s.y * 0.42f).toInt())
             .coerceIn(0, (s.y - size).coerceAtLeast(0))
         try { wm.updateViewLayout(v, lp) } catch (e: Exception) { }
     }

     private fun hideStopButton() {
         try { stopWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         stopWin = null
         stopLp = null
     }

     // --- Мини-панель «Голос» / «Скорость» (открывается с плитки) ---

     private fun showMiniPanel(kind: String) {
         if (miniWin != null) return
         miniKind = kind
         val card = LinearLayout(this).apply {
             orientation = LinearLayout.VERTICAL
             background = rounded(cardBg, 18f)
             setPadding(dp(14), dp(12), dp(14), dp(12))
         }
         val lp = overlayLp(WindowManager.LayoutParams.WRAP_CONTENT, WindowManager.LayoutParams.WRAP_CONTENT, true)
         val s = screenSize()
         val w = dp(240)
         val base = mainLp
         lp.x = (((base?.x ?: (s.x - dp(76))) - w - dp(8)).coerceIn(0, (s.x - w).coerceAtLeast(0)))
         lp.y = ((base?.y ?: (s.y * 0.42f).toInt()) + dp(20)).coerceIn(0, (s.y - dp(240)).coerceAtLeast(0))
         try { wm.addView(card, lp) } catch (e: Exception) { return }
         miniWin = card
         miniLp = lp
         rebuildMiniPanel()
     }

     private fun rebuildMiniPanel() {
         val card = miniWin ?: return
         card.removeAllViews()

         val title = TextView(this).apply {
             text = if (miniKind == "speed") "Скорость чтения" else "Голос"
             textSize = 15f
             setTextColor(txtTitle)
             setPadding(0, 0, 0, dp(10))
         }
         card.addView(title)

         if (miniKind == "speed") {
             val rate = prefs.getFloat("rate", 1.0f)
             val pct = TextView(this).apply {
                 text = Rates.percent(rate).toString() + "%"
                 textSize = 22f
                 setTextColor(txtTitle)
                 gravity = Gravity.CENTER
                 setPadding(0, 0, 0, dp(6))
             }
             speedPctText = pct
             card.addView(pct)
             val r1 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }
             r1.addView(miniBtn("−", false) { changeRate(-Rates.STEP) })
             r1.addView(miniBtn("1×", false) { changeRate(1.0f - rate) })
             r1.addView(miniBtn("+", false) { changeRate(Rates.STEP) })
             card.addView(r1)
             val r2 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }
             for (p in intArrayOf(50, 100, 150, 200)) {
                 val target = p / 100f
                 r2.addView(miniBtn("$p%", rate == target) { changeRate(target - rate) })
             }
             card.addView(r2)
             val hint = TextView(this).apply {
                 text = "50…200%, шаг 25%"
                 textSize = 12f
                 setTextColor(txtSub)
                 gravity = Gravity.CENTER
                 setPadding(0, dp(6), 0, 0)
             }
             card.addView(hint)
         } else {
             val gender = prefs.getString("gender", "female")
             val r1 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }
             r1.addView(miniBtn("♀", gender == "female") { setGender("female") })
             r1.addView(miniBtn("♂", gender == "male") { setGender("male") })
             r1.addView(miniBtn("≡", false) {
                 closeMiniPanel()
                 openVoicePicker()
             })
             card.addView(r1)
             val r2 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }
             r2.addView(miniBtn("♪", false) {
                 closeMiniPanel()
                 speakNowSilentPreview("Привет! Это мой голос.")
             })
             r2.addView(miniBtn("⚙", false) {
                 closeMiniPanel()
                 try {
                     val i = Intent("com.android.settings.TTS_SETTINGS")
                     i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                     startActivity(i)
                 } catch (e: Exception) {
                     Toast.makeText(this, "Настройки TTS недоступны", Toast.LENGTH_SHORT).show()
                 }
             })
             card.addView(r2)
             val hint = TextView(this).apply {
                 text = "≡ — список голосов · ⚙ — настройки TTS"
                 textSize = 12f
                 setTextColor(txtSub)
                 gravity = Gravity.CENTER
                 setPadding(0, dp(6), 0, 0)
             }
             card.addView(hint)
         }

         card.addView(TextView(this).apply {
             text = "✕ Закрыть"
             textSize = 13f
             setTextColor(txtSub)
             gravity = Gravity.CENTER
             setPadding(0, dp(10), 0, 0)
             setOnClickListener { closeMiniPanel() }
         })

         val lp = miniLp
         if (lp != null) try { wm.updateViewLayout(card, lp) } catch (e: Exception) { }
     }

     private fun closeMiniPanel() {
         try { miniWin?.let { wm.removeView(it) } } catch (e: Exception) { }
         miniWin = null
         miniLp = null
         miniKind = ""
         speedPctText = null
     }

     /** Дописать распознанный фрагмент в буфер авточтения и показать его снизу. */
     private fun appendRead(text: String) {
         if (readBuffer.isNotEmpty()) readBuffer.append('\n')
         readBuffer.append(text)
         if (readBuffer.length > 6000) readBuffer.delete(0, readBuffer.length - 6000)
         preview = readBuffer.toString().trim()
         previewText?.text = preview
         previewText?.post { previewText?.let { v -> v.scrollTo(0, v.layout?.height ?: 0) } }
     }

