     /** Плитка сеточного меню: короткий глиф + подпись, тап/долгий тап. */
     private inner class Tile(
         val glyph: String?,
         val title: String,
         val active: Boolean = false,
         val onLong: (() -> Unit)? = null,
         val onClick: () -> Unit
     )

     /** Раскладывает плитки по 2 в ряд (сетка). */
     private fun addGrid(tiles: List<Tile>) {
         val card = panelCard ?: return
         var i = 0
         while (i < tiles.size) {
             val line = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
             for (j in 0 until 2) {
                 val idx = i + j
                 val lp = LinearLayout.LayoutParams(0, dp(50), 1f).apply {
                     setMargins(dp(4), dp(4), dp(4), dp(4))
                 }
                 if (idx < tiles.size) line.addView(tileView(tiles[idx]), lp)
                 else line.addView(View(this), lp)
             }
             card.addView(line)
             i += 2
         }
     }

     private fun tileView(t: Tile): View {
         val row = LinearLayout(this).apply {
             orientation = LinearLayout.HORIZONTAL
             gravity = Gravity.CENTER
             background = rounded(if (t.active) btnBgAccent else btnBg, 12f)
             setPadding(dp(6), dp(4), dp(6), dp(4))
             isClickable = true
             setOnClickListener { runCatching(t.onClick) }
             if (t.onLong != null) setOnLongClickListener { runCatching(t.onLong); true }
         }
         if (t.glyph != null) {
             row.addView(TextView(this).apply {
                 text = t.glyph
                 textSize = 16f
                 setTextColor(txtTitle)
             })
         }
         row.addView(TextView(this).apply {
             text = t.title
             textSize = 13f
             setTextColor(txtTitle)
             maxLines = 2
             ellipsize = android.text.TextUtils.TruncateAt.END
             if (t.glyph != null) setPadding(dp(6), 0, 0, 0)
         })
         return row
     }

     private fun rebuildPanel() {
         val card = panelCard ?: return
         card.removeAllViews()

         // превью распознанного текста / статус
         val pv = TextView(this).apply {
             val base = if (preview.isNotBlank()) preview else "Рамка: ${regionLabel()}. Тапни «OCR скан» или «Авточтение»."
             text = base
             textSize = 13f
             setTextColor(txtSub)
             setPadding(dp(10), dp(6), dp(10), dp(8))
             maxLines = 10
             isVerticalScrollBarEnabled = true
             movementMethod = android.text.method.ScrollingMovementMethod()
         }
         previewText = pv
         card.addView(pv)
         divider()

         // Сетка основных действий (по 2 в ряд)
         val engId = engineId()
         val trOn = prefs.getBoolean("translate", false)
         addGrid(
             listOf(
                 Tile("▤", "OCR скан") { scanOnceOrAsk() },
                 if (autoReading) Tile("■", "Стоп чтения", active = true) { stopAutoRead() }
                 else Tile("▶", "Авточтение") { startAutoReadOrAsk() },
                 Tile("◎", "Движок") { switchEngine(Engines.next(engId)) },
                 Tile("⇄", if (trOn) "Перевод ВКЛ" else "Перевод", active = trOn) {
                     prefs.edit().putBoolean("translate", !trOn).apply()
                     Toast.makeText(this, if (!trOn) "Перевод включён" else "Перевод выключен", Toast.LENGTH_SHORT).show()
                     rebuildPanel()
                 },
                 Tile("▢", "Область: ${regionLabel()}") { cycleRegionPreset() },
                 Tile("⚙", "Все настройки") {
                     try {
                         val i = Intent(this, MainActivity::class.java)
                         i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                         startActivity(i)
                     } catch (e: Exception) { }
                 },
                 Tile("♪", "Голос") { showMiniPanel("voice") },
                 Tile("⏱", "Скорость") { showMiniPanel("speed") },
                 Tile("↻", "Чтение: ${ReadingOrder.short(readOrderMode())}") { cycleReadOrder() },
                 Tile("·", "Порядок 1..${if (layoutBlocks.isEmpty()) "—" else layoutBlocks.size}",
                     active = layoutBlocks.isNotEmpty()) { if (layoutBlocks.isEmpty()) rebuildPanel() }
             )
         )

         divider()

         // Нижняя сетка: свернуть / скрыть / закрыть
         addGrid(
             listOf(
                 Tile("▾", "Панель вниз") { setExpanded(false) },
                 Tile("◌", "Скрыть 30 с") {
                     showMain(false)
                     ui.postDelayed({ showMain(true) }, 30_000)
                 },
                 Tile("✕", "Закрыть", onLong = { stopSelf() }) {
                     Toast.makeText(this, "Удерживайте «Закрыть», чтобы выключить", Toast.LENGTH_SHORT).show()
                 }
             )
         )
     }

     private fun switchEngine(id: String) {
         prefs.edit().putString("ocr_engine", id).apply()
         android.util.Log.i("OverlayOcr", "engine -> $id")
         rebuildPanel()
         val label = engineTitle()
         Toast.makeText(this, "Движок: $label", Toast.LENGTH_SHORT).show()
     }

     private fun setGender(g: String) {
         prefs.edit().putString("gender", g).apply()
         rebuildPanel()
         if (miniKind == "voice") rebuildMiniPanel()
     }

     private fun changeRate(delta: Float) {
         val cur = prefs.getFloat("rate", 1.0f)
         val r = Rates.step(cur, delta)
         prefs.edit().putFloat("rate", r).apply()
         try { tts?.setSpeechRate(r) } catch (e: Exception) { }
         speedPctText?.text = Rates.percent(r).toString() + "%"
         rebuildPanel()
     }

     private fun cycleReadOrder() {
         val next = ReadingOrder.next(readOrderMode())
         prefs.edit().putString("read_order", next).apply()
         // Пересортируем блоки последнего распознавания новым направлением.
         if (layoutBlocks.isNotEmpty()) {
             layoutBlocks = ReadingOrder.order(layoutBlocks, next)
             activeBlock = -1
             refreshFrame()
         }
         Toast.makeText(this, "Чтение: ${ReadingOrder.label(next)}", Toast.LENGTH_SHORT).show()
         rebuildPanel()
     }

     // ------------------------------------------------------------------
     // MediaProjection
     // ------------------------------------------------------------------

     private fun grantProjection(resultCode: Int, data: Intent) {
         try {
             // Android 14 требует, чтобы foreground-сервис с типом mediaProjection
             // уже работал ДО getMediaProjection()/createVirtualDisplay(): иначе
             // система тут же останавливает проекцию (onStop → «захват выключен»).
             ensureForeground(true)
             val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE) as MediaProjectionManager
             val mp = mpm.getMediaProjection(resultCode, data)
             if (Build.VERSION.SDK_INT >= 29) {
                 // Callback во всех версиях, где он есть: если пользователь или
                 // система остановили захват, сервис должен узнать об этом
                 // сразу, а не продолжать показывать «работает».
                 mp.registerCallback(object : MediaProjection.Callback() {
                     override fun onStop() {
                         projection = null
                         projectionGranted = false
                         autoReading = false
                         speakGen++
                         releaseDisplay()
                         preview = "⚠ Захват экрана остановлен — повторите скан"
                         ui.post {
                             previewText?.text = preview
                             rebuildPanel()
                             refreshFrame()
                             notifyStatus(preview)
                         }
                     }
                 }, ui)
             }
             projection = mp
             projectionGranted = true
             bindProjection(mp)
         } catch (e: Exception) {
             try { ensureForeground(false) } catch (e2: Exception) { }
             Toast.makeText(this, "Захват экрана не запустился: ${e.message}", Toast.LENGTH_LONG).show()
         }
     }

     private fun scanOnceOrAsk() {
         if (!projectionGranted) CaptureConsentActivity.request(this, "scan") else scanOnce()
     }

     private fun startAutoReadOrAsk() {
         if (!projectionGranted) CaptureConsentActivity.request(this, "read") else startAutoRead()
     }

